import time, random, math, heapq

def _infeasible(msg):
    return {"status": "infeasible", "reason": msg}

def _build(inp):
    res = inp.get("resources") or {}
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    for r in rnames:
        cal = sorted([(int(a), int(b)) for a, b in (res[r].get("calendar") or [[0, 0]])])
        if not cal or cal[0][0] != 0:
            cal = [(0, 0)] + cal
        cals.append(cal)
        maxcap.append(cal[-1][1])
    jobs = inp.get("jobs") or []
    ids = [str(j["id"]) for j in jobs]
    jidx = {}
    for i, s in enumerate(ids):
        if s not in jidx:
            jidx[s] = i
    n = len(jobs)
    preds = []
    modes = []
    for i, j in enumerate(jobs):
        pl = []
        for p in (j.get("after") or []):
            p = str(p)
            if p not in jidx:
                return None, "job %s references unknown predecessor %s" % (ids[i], p)
            pl.append(jidx[p])
        preds.append(sorted(set(pl)))
        ml = []
        for mi, m in enumerate(j.get("modes") or []):
            req = m.get("requires") or {}
            ok = True
            rl = []
            for r, u in req.items():
                u = int(u)
                if r not in ridx:
                    if u > 0:
                        ok = False
                        break
                    continue
                if u > maxcap[ridx[r]]:
                    ok = False
                    break
                if u > 0:
                    rl.append((ridx[r], u))
            if ok:
                ml.append((mi, max(1, int(m.get("duration", 1))), rl))
        if not ml:
            return None, "job %s has no feasible mode" % ids[i]
        modes.append(ml)
    succ = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        for p in preds[i]:
            succ[p].append(i)
            indeg[i] += 1
    topo = []
    st = [i for i in range(n) if indeg[i] == 0]
    deg = indeg[:]
    while st:
        x = st.pop()
        topo.append(x)
        for s in succ[x]:
            deg[s] -= 1
            if deg[s] == 0:
                st.append(s)
    if len(topo) < n:
        return None, "precedence relation contains a cycle"
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    due = [j.get("due") for j in jobs]
    due = [None if d is None else int(d) for d in due]
    w = [int(j.get("weight", 0) or 0) for j in jobs]
    maxbp = max([c[-1][0] for c in cals] + [0])
    H = maxbp + max(rel + [0]) + sum(max(m[1] for m in ml) for ml in modes) + 30
    base = []
    for ri in range(len(rnames)):
        cal = cals[ri]
        arr = []
        for k in range(len(cal)):
            a = cal[k][0]
            b = cal[k + 1][0] if k + 1 < len(cal) else H
            if b > a:
                arr.extend([cal[k][1]] * (b - a))
        if len(arr) < H:
            arr.extend([cal[-1][1]] * (H - len(arr)))
        base.append(arr[:H])
    return {"n": n, "ids": ids, "preds": preds, "succ": succ, "modes": modes, "topo": topo,
            "rel": rel, "due": due, "w": w, "base": base, "maxcap": maxcap, "H": H}, None

def _solve(inp, t0, budget):
    P, err = _build(inp)
    if P is None:
        return _infeasible(err)
    n = P["n"]
    ids = P["ids"]
    if n == 0:
        return {"status": "ok", "schedule": {}}
    deadline = t0 + budget
    preds = P["preds"]; succ = P["succ"]; modes = P["modes"]; topo = P["topo"]
    rel = P["rel"]; due = P["due"]; w = P["w"]; base = P["base"]; maxcap = P["maxcap"]
    INF = float("inf")
    rng = random.Random(12345)

    def place(av, est, d, req):
        t = est
        while True:
            moved = False
            for r, u in req:
                a = av[r]
                if t + d > len(a):
                    a.extend([maxcap[r]] * (t + d - len(a) + 64))
                seg = a[t:t + d]
                if min(seg) < u:
                    k = d - 1
                    while seg[k] >= u:
                        k -= 1
                    t = t + k + 1
                    moved = True
                    break
            if not moved:
                return t

    def commit(av, t, d, req):
        for r, u in req:
            a = av[r]
            for x in range(t, t + d):
                a[x] -= u

    def tard(j, f):
        if due[j] is None or w[j] == 0:
            return 0
        return w[j] * (f - due[j]) if f > due[j] else 0

    def decode(order, ms):
        av = [a[:] for a in base]
        fin = [0] * n
        start = [0] * n
        cost = 0
        mk = 0
        for j in order:
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            m = modes[j][ms[j]]
            d = m[1]
            t = place(av, est, d, m[2])
            commit(av, t, d, m[2])
            start[j] = t
            f = t + d
            fin[j] = f
            if f > mk:
                mk = f
            cost += tard(j, f)
        return cost + mk, start

    mfrac = []
    for j in range(n):
        fl = []
        for (_, d, req) in modes[j]:
            s = 0.0
            for r, u in req:
                s += u / max(1, maxcap[r])
            fl.append(s * d)
        mfrac.append(fl)

    def decode_greedy(order, lam):
        av = [a[:] for a in base]
        fin = [0] * n
        start = [0] * n
        ms = [0] * n
        cost = 0
        mk = 0
        for j in order:
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            ml = modes[j]
            if len(ml) == 1:
                bi = 0
                bt = place(av, est, ml[0][1], ml[0][2])
            else:
                bs = INF; bi = 0; bt = 0
                for mi in range(len(ml)):
                    d = ml[mi][1]
                    t = place(av, est, d, ml[mi][2])
                    f = t + d
                    sc = f + tard(j, f) + lam * mfrac[j][mi]
                    if sc < bs:
                        bs = sc; bi = mi; bt = t
            m = ml[bi]
            commit(av, bt, m[1], m[2])
            start[j] = bt
            ms[j] = bi
            f = bt + m[1]
            fin[j] = f
            if f > mk:
                mk = f
            cost += tard(j, f)
        return cost + mk, start, ms

    mind = [min(m[1] for m in modes[j]) for j in range(n)]
    es = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            if es[p] + mind[p] > e:
                e = es[p] + mind[p]
        es[j] = e
    T = max(es[j] + mind[j] for j in range(n))
    lf = [T] * n
    dd = [INF] * n
    for j in reversed(topo):
        v = T
        dv = INF if (due[j] is None or w[j] == 0) else due[j]
        for s in succ[j]:
            if lf[s] - mind[s] < v:
                v = lf[s] - mind[s]
            if dd[s] - mind[s] < dv:
                dv = dd[s] - mind[s]
        lf[j] = v
        dd[j] = dv
    wsum = [0] * n
    for j in reversed(topo):
        s = w[j] if due[j] is not None else 0
        for x in succ[j]:
            s += wsum[x]
        wsum[j] = s
    keysets = []
    keysets.append([float(lf[j]) for j in range(n)])
    keysets.append([float(min(lf[j], dd[j])) for j in range(n)])
    keysets.append([float(lf[j] - mind[j]) for j in range(n)])
    keysets.append([float(min(lf[j], dd[j]) - mind[j]) for j in range(n)])
    keysets.append([float(es[j]) for j in range(n)])
    keysets.append([float(min(lf[j], dd[j] - 2.0 * math.log1p(wsum[j]))) for j in range(n)])
    avgd = sum(mind) / n

    def order_from_keys(key):
        deg = [len(preds[j]) for j in range(n)]
        h = [(key[j], j) for j in range(n) if deg[j] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, x = heapq.heappop(h)
            out.append(x)
            for s in succ[x]:
                deg[s] -= 1
                if deg[s] == 0:
                    heapq.heappush(h, (key[s], s))
        return out

    def normalize(start):
        return sorted(range(n), key=lambda j: (start[j], j))

    c, st, ms = decode_greedy(topo, 0.0)
    best = (c, normalize(st), ms)
    it = 0
    samp_end = t0 + budget * 0.35
    lams = [0.0, 0.0, 0.3, 1.0, 3.0]
    while True:
        if it >= len(keysets) * 2 and time.process_time() > samp_end:
            break
        if time.process_time() > deadline:
            break
        ks = keysets[it % len(keysets)]
        if it < len(keysets) * 2:
            noise = 0.0
            lam = 0.0 if it < len(keysets) else 0.5
        else:
            noise = avgd * rng.choice([0.5, 1.0, 2.0, 4.0])
            lam = rng.choice(lams)
        key = [ks[j] + rng.random() * noise for j in range(n)] if noise > 0 else ks
        order = order_from_keys(key)
        c, st, ms = decode_greedy(order, lam)
        if c < best[0]:
            best = (c, normalize(st), ms)
        it += 1

    cur_c, cur_o, cur_m = best[0], best[1][:], best[2][:]
    multi = [j for j in range(n) if len(modes[j]) > 1]
    T0 = max(1.0, 0.03 * cur_c)
    Tend = 0.3
    sa_start = time.process_time()
    sa_len = max(1e-6, deadline - sa_start)
    stepc = 0
    temp = T0
    last_imp = 0
    while True:
        if stepc % 8 == 0:
            now = time.process_time()
            if now > deadline:
                break
            frac = (now - sa_start) / sa_len
            temp = T0 * (Tend / T0) ** frac
        stepc += 1
        o = cur_o
        m = cur_m
        r = rng.random()
        no = o
        nm = m
        if multi and r < 0.3:
            j = rng.choice(multi)
            k = rng.randrange(len(modes[j]) - 1)
            if k >= m[j]:
                k += 1
            nm = m[:]
            nm[j] = k
        else:
            pos = {x: i for i, x in enumerate(o)}
            j = o[rng.randrange(n)]
            i = pos[j]
            lo = 0
            for p in preds[j]:
                if pos[p] + 1 > lo:
                    lo = pos[p] + 1
            hi = n - 1
            for s in succ[j]:
                if pos[s] - 1 < hi:
                    hi = pos[s] - 1
            if hi <= lo:
                continue
            if rng.random() < 0.5:
                np_ = rng.randint(max(lo, i - 6), min(hi, i + 6))
            else:
                np_ = rng.randint(lo, hi)
            if np_ == i:
                continue
            no = o[:]
            no.pop(i)
            no.insert(np_, j)
            if multi and rng.random() < 0.15 and len(modes[j]) > 1:
                nm = m[:]
                nm[j] = rng.randrange(len(modes[j]))
        c, st = decode(no, nm)
        dlt = c - cur_c
        if dlt <= 0 or rng.random() < math.exp(-dlt / temp):
            cur_c = c
            cur_o = normalize(st) if rng.random() < 0.5 else no
            cur_m = nm
            if c < best[0]:
                best = (c, normalize(st), nm[:])
                last_imp = stepc
        if stepc - last_imp > 4000:
            cur_c, cur_o, cur_m = best[0], best[1][:], best[2][:]
            last_imp = stepc

    c, st = decode(best[1], best[2])
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": int(st[j]), "mode": int(modes[j][best[2][j]][0])}
    return {"status": "ok", "schedule": sched}

def solve(state, params):
    t0 = time.process_time()
    try:
        out = _solve(state["input"], t0, 0.72)
    except Exception:
        out = None
    if out is None:
        out = _infeasible("error")
    state["output"] = out
    return state

