            nm[j] = k
        else:
            pos = {x: i for i, x in enumerate(o)}
            j = o[rng.randrange(n)]
            i = pos[j]
            lo = 0
            for p in preds[j]:
                if pos[p] + 1 > lo:
                    lo = pos[p] + 1
            hi = n - 1
            for s in succ[j]:
                if pos[s] - 1 < hi:
                    hi = pos[s] - 1
            if hi <= lo:
                continue
            if rng.random() < 0.5:
                np_ = rng.randint(max(lo, i - 6), min(hi, i + 6))
            else:
                np_ = rng.randint(lo, hi)
            if np_ == i:
                continue
            no = o[:]
            no.pop(i)
            no.insert(np_, j)
            if multi and rng.random() < 0.15 and len(modes[j]) > 1:
                nm = m[:]
                nm[j] = rng.randrange(len(modes[j]))
        c, st = decode(no, nm)
        dlt = c - cur_c
        if dlt <= 0 or rng.random() < math.exp(-dlt / temp):
            cur_c = c
            cur_o = normalize(st) if rng.random() < 0.5 else no
            cur_m = nm
            if c < best[0]:
                best = (c, normalize(st), nm[:])
                last_imp = stepc
        if stepc - last_imp > 4000:
            cur_c, cur_o, cur_m = best[0], best[1][:], best[2][:]
            last_imp = stepc

    c, st = decode(best[1], best[2])
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": int(st[j]), "mode": int(modes[j][best[2][j]][0])}
    return {"status": "ok", "schedule": sched}

def solve(state, params):
    t0 = time.process_time()
    try:
        out = _solve(state["input"], t0, 0.72)
    except Exception:
        out = None
    if out is None:
        out = _infeasible("error")
    state["output"] = out
    return state

import time, random, heapq

def solve(state, params):
    t0 = time.process_time()
    inp = state["input"]
    try:
        state["output"] = _solve(inp, t0)
    except Exception as ex:
        state["output"] = {"status": "infeasible", "reason": "error: " + str(ex)[:80]}
    return state

def _solve(inp, t0):
    budget = 0.78
    res = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    lastbp = 0
    for r in rnames:
        cal = res[r].get("calendar", []) or [[0, 0]]
        cal = sorted([(int(a), int(b)) for a, b in cal])
        cals.append(cal)
        maxcap.append(cal[-1][1])
        lastbp = max(lastbp, cal[-1][0])
    n = len(jobs)
    ids = [str(j["id"]) for j in jobs]
    jidx = {s: i for i, s in enumerate(ids)}
    preds = []
    for j in jobs:
        ps = []
        for p in j.get("after", []) or []:
            p = str(p)
            if p not in jidx:
                return {"status": "infeasible", "reason": "job %s references unknown predecessor %s" % (j["id"], p)}
            q = jidx[p]
            if q not in ps:
                ps.append(q)
        preds.append(ps)
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    topo = [i for i in range(n) if indeg[i] == 0]
    k = 0
    while k < len(topo):
        x = topo[k]; k += 1
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                topo.append(s)
    if len(topo) < n:
        return {"status": "infeasible", "reason": "precedence cycle"}
    modes = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes", []) or []):
            d = int(m["duration"])
            req = []
            ok = True
            for rn, u in (m.get("requires", {}) or {}).items():
                u = int(u)
                if rn not in ridx:
                    ok = False; break
                if u > maxcap[ridx[rn]]:
                    ok = False; break
                if u > 0:
                    req.append((ridx[rn], u))
            if ok:
                ml.append((mi, d, req))
        if not ml:
            return {"status": "infeasible", "reason": "job %s has no feasible mode" % j["id"]}
        modes.append(ml)
    if n == 0:
        return {"status": "ok", "schedule": {}}
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    due = [j.get("due") for j in jobs]
    wt = [int(j.get("weight", 0) or 0) if due[i] is not None else 0 for i, j in enumerate(jobs)]
    duev = [int(due[i]) if due[i] is not None else 10**9 for i in range(n)]
    H = max(lastbp, max(rel)) + sum(max(m[1] for m in modes[i]) for i in range(n)) + 2
    base = []
    for ri in range(len(rnames)):
        cal = cals[ri]
        arr = [0] * H
        for k2, (a, c) in enumerate(cal):
            b = cal[k2 + 1][0] if k2 + 1 < len(cal) else H
            a2 = max(0, min(a, H)); b2 = max(0, min(b, H))
            if b2 > a2:
                arr[a2:b2] = [c] * (b2 - a2)
        base.append(arr)
    mind = [min(m[1] for m in modes[i]) for i in range(n)]
    nm = [len(modes[i]) for i in range(n)]

    def decode(order, mvec, greedy, noise=0.0, rnd=None):
        av = [a[:] for a in base]
        fin = [0] * n
        st = [0] * n
        used = [0] * n
        mk = 0
        tard = 0
        for j in order:
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            if greedy or mvec[j] < 0:
                cand = range(nm[j])
            else:
                cand = (mvec[j],)
            best = None
            for mi in cand:
                _, d, req = modes[j][mi]
                reqs = [(av[r], u) for r, u in req]
                t = est
                while True:
                    ok = True
                    e = t + d
                    for arr, u in reqs:
                        for x in range(t, e):
                            if arr[x] < u:
                                t = x + 1; ok = False; break
                        if not ok:
                            break
                    if ok:
                        break
                f = t + d
                sc = f + wt[j] * max(0, f - duev[j])
                if f > mk:
                    sc += (f - mk) * 0.5
                if noise and rnd is not None:
                    sc += rnd.random() * noise
                if best is None or sc < best[0]:
                    best = (sc, mi, t, f)
            _, mi, t, f = best
            for r, u in modes[j][mi][2]:
                arr = av[r]
                for x in range(t, f):
                    arr[x] -= u
            st[j] = t; fin[j] = f; used[j] = mi
            if f > mk: mk = f
            if wt[j] and f > duev[j]:
                tard += wt[j] * (f - duev[j])
        return mk + tard, st, used

    tail = [0] * n
    for j in reversed(topo):
        tl = 0
        for s in succs[j]:
            v = tail[s] + mind[s]
            if v > tl: tl = v
        tail[j] = tl
    T = max(tail[j] + mind[j] + rel[j] for j in range(n))
    lft = [T - tail[j] for j in range(n)]
    dl = [10**9] * n
    for j in reversed(topo):
        v = duev[j] if wt[j] > 0 else 10**9
        for s in succs[j]:
            w = dl[s] - mind[s]
            if w < v: v = w
        dl[j] = v

    def build_order(key, rnd, noise):
        indeg2 = [len(preds[i]) for i in range(n)]
        h = []
        for i in range(n):
            if indeg2[i] == 0:
                heapq.heappush(h, (key[i] + (rnd.random() * noise if noise else 0), i))
        out = []
        while h:
            _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                indeg2[s] -= 1
                if indeg2[s] == 0:
                    heapq.heappush(h, (key[s] + (rnd.random() * noise if noise else 0), s))
        return out

    keys = []
    keys.append([float(lft[i]) for i in range(n)])
    keys.append([float(min(lft[i], dl[i])) for i in range(n)])
    keys.append([float(min(lft[i], dl[i] - mind[i])) - 0.01 * wt[i] for i in range(n)])
    keys.append([float(min(lft[i], dl[i])) + rel[i] * 0.3 for i in range(n)])
    keys.append([float(-tail[i] - mind[i]) for i in range(n)])
    keys.append([float(rel[i]) + min(lft[i], dl[i]) * 0.5 for i in range(n)])

    rnd = random.Random(12345)
    best = None
    def consider(cost, st, used):
        nonlocal best
        if best is None or cost < best[0]:
            best = (cost, st[:], used[:])
    pool = []
    for key in keys:
        o = build_order(key, rnd, 0)
        c, st, used = decode(o, None, True)
        consider(c, st, used)
        pool.append((c, sorted(range(n), key=lambda x: (st[x], x)), used))
        if time.process_time() - t0 > budget * 0.5:
            break
    span = max(1.0, float(T) * 0.15)
    it = 0
    while time.process_time() - t0 < budget * 0.35:
        key = keys[it % len(keys)]
        it += 1
        o = build_order(key, rnd, span * rnd.random())
        c, st, used = decode(o, None, True, noise=rnd.random() * 2.0, rnd=rnd)
        consider(c, st, used)
        pool.append((c, sorted(range(n), key=lambda x: (st[x], x)), used))
    pool.sort(key=lambda x: x[0])
    cur_c, cur_o, cur_m = pool[0][0], pool[0][1][:], pool[0][2][:]
    pos = [0] * n
    stall = 0
    maxnm = max(nm)
    while time.process_time() - t0 < budget:
        o = cur_o[:]
        m = cur_m[:]
        r = rnd.random()
        greedy = False
        if r < 0.25 and maxnm > 1:
            j = rnd.randrange(n)
            tries = 0
            while nm[j] == 1 and tries < 20:
                j = rnd.randrange(n); tries += 1
            if nm[j] > 1:
                m[j] = (m[j] + 1 + rnd.randrange(nm[j] - 1)) % nm[j]
        if r >= 0.15:
            nmoves = 1 + (1 if rnd.random() < 0.3 else 0) + (1 if (stall > 200 and rnd.random() < 0.5) else 0)
            for _ in range(nmoves):
                for i, x in enumerate(o):
                    pos[x] = i
                j = rnd.randrange(n)
                lo = 0
                for p in preds[j]:
                    if pos[p] + 1 > lo: lo = pos[p] + 1
                hi = n - 1
                for s in succs[j]:
                    if pos[s] - 1 < hi: hi = pos[s] - 1
                i0 = pos[j]
                if hi <= lo:
                    continue
                d = int(rnd.gauss(0, 4)) or (1 if rnd.random() < 0.5 else -1)
                tgt = max(lo, min(hi, i0 + d))
                if tgt == i0:
                    continue
                o.pop(i0)
                o.insert(tgt, j)
        if rnd.random() < 0.05:
            greedy = True
        c, st, used = decode(o, m, greedy)
        if c <= cur_c:
            if c < cur_c:
                stall = 0
            else:
                stall += 1
            cur_c = c
            cur_o = sorted(range(n), key=lambda x: (st[x], x))
            cur_m = used
            consider(c, st, used)
        else:
            stall += 1
        if stall > 600:
            stall = 0
            cand = pool[rnd.randrange(min(len(pool), 5))]
            cur_c, cur_o, cur_m = cand[0], cand[1][:], cand[2][:]
    _, st, used = best
    sched = {}
    for i in range(n):
        sched[ids[i]] = {"start": int(st[i]), "mode": int(modes[i][used[i]][0])}
    return {"status": "ok", "schedule": sched}

import time, random, heapq

def solve(state, params):
    T0 = time.process_time()
    BUDGET = 0.72
    inp = state["input"]
    res = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    maxbp = 0
    for r in rnames:
        cal = sorted([(int(a), int(b)) for a, b in (res[r].get("calendar") or [[0, 0]])])
        if not cal:
            cal = [(0, 0)]
        cals.append(cal)
        maxcap.append(cal[-1][1])
        maxbp = max(maxbp, cal[-1][0])
    n = len(jobs)
    ids = [str(j["id"]) for j in jobs]
    jidx = {}
    for i, s in enumerate(ids):
        jidx[s] = i
    preds = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        for p in j.get("after", []) or []:
            p = str(p)
            if p not in jidx:
                state["output"] = {"status": "infeasible", "reason": "unknown predecessor %s of job %s" % (p, ids[i])}
                return state
            pi = jidx[p]
            if pi not in preds[i]:
                preds[i].append(pi)
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    topo = [i for i in range(n) if indeg[i] == 0]
    k = 0
    while k < len(topo):
        x = topo[k]; k += 1
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                topo.append(s)
    if len(topo) < n:
        state["output"] = {"status": "infeasible", "reason": "precedence cycle"}
        return state
    modes = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes", []) or []):
            d = int(m["duration"])
            ok = True
            req = []
            for rn, u in (m.get("requires", {}) or {}).items():
                u = int(u)
                if rn not in ridx or u > maxcap[ridx[rn]]:
                    ok = False; break
                if u > 0:
                    req.append((ridx[rn], u))
            if ok:
                ml.append((mi, d, req))
        if not ml:
            state["output"] = {"status": "infeasible", "reason": "job %s has no feasible mode" % ids[i]}
            return state
        modes.append(ml)
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    rel = [int(j.get("release", 0) or 0) for j in jobs]
    due = [j.get("due") for j in jobs]
    wt = [int(j.get("weight", 0) or 0) for j in jobs]
    H = maxbp + max(rel + [0]) + sum(max(m[1] for m in ml) for ml in modes) + 30
    R = len(rnames)
    base = []
    for r in range(R):
        cal = cals[r]
        arr = [0] * H
        for q, (a, c) in enumerate(cal):
            b = cal[q + 1][0] if q + 1 < len(cal) else H
            a = max(0, a); b = min(H, b)
            if a < b:
                arr[a:b] = [c] * (b - a)
        base.append(arr)
    tard = [(i, int(due[i]), wt[i]) for i in range(n) if due[i] is not None and wt[i] > 0]

    def earliest(avail, t, d, req):
        while True:
            okk = True
            for r, u in req:
                a = avail[r]
                seg = a[t:t + d]
                if min(seg) < u:
                    kk = len(seg) - 1
                    while seg[kk] >= u:
                        kk -= 1
                    t = t + kk + 1
                    okk = False
                    break
            if okk:
                return t

    def sgs(order, mfix):
        avail = [a[:] for a in base]
        st = [0] * n; fin = [0] * n; mch = [0] * n
        for j in order:
            e = rel[j]
            for p in preds[j]:
                if fin[p] > e:
                    e = fin[p]
            mf = mfix[j]
            ml = modes[j]
            bm = 0; bt = e
            if mf >= 0:
                m = ml[mf]
                bt = earliest(avail, e, m[1], m[2]); bm = mf
            else:
                bf = None
                for q, m in enumerate(ml):
                    t = earliest(avail, e, m[1], m[2])
                    f = t + m[1]
                    if bf is None or f < bf:
                        bf = f; bm = q; bt = t
            m = ml[bm]
            d = m[1]
            for r, u in m[2]:
                a = avail[r]
                for x in range(bt, bt + d):
                    a[x] -= u
            st[j] = bt; fin[j] = bt + d; mch[j] = bm
        c = max(fin)
        for i, dd, w in tard:
            if fin[i] > dd:
                c += w * (fin[i] - dd)
        return c, st, mch

    mind = [min(m[1] for m in ml) for ml in modes]
    tail = [0] * n
    for j in reversed(topo):
        t = 0
        for s in succs[j]:
            if tail[s] > t:
                t = tail[s]
        tail[j] = t + mind[j]
    head = [0] * n
    for j in topo:
        h = rel[j]
        for p in preds[j]:
            if head[p] + mind[p] > h:
                h = head[p] + mind[p]
        head[j] = h
    BIG = 10 ** 7
    dl = [BIG] * n
    for j in reversed(topo):
        v = BIG
        if due[j] is not None and wt[j] > 0:
            v = int(due[j])
        for s in succs[j]:
            if dl[s] < BIG and dl[s] - mind[s] < v:
                v = dl[s] - mind[s]
        dl[j] = v
    cp = max([head[j] + tail[j] for j in range(n)] + [0])
    lst = [cp - tail[j] for j in range(n)]

    def build(key):
        dg = [len(preds[i]) for i in range(n)]
        h = [(key[i], i) for i in range(n) if dg[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                dg[s] -= 1
                if dg[s] == 0:
                    heapq.heappush(h, (key[s], s))
        return out

    rng = random.Random(12345)
    keys = []
    keys.append([(lst[j], 0) for j in range(n)])
    keys.append([(min(lst[j], dl[j] - tail[j]), lst[j]) for j in range(n)])
    keys.append([(dl[j] - tail[j], lst[j]) for j in range(n)])
    keys.append([(head[j], lst[j]) for j in range(n)])
    keys.append([(min(lst[j], dl[j] - tail[j] - (wt[j] if dl[j] < BIG else 0)), -tail[j]) for j in range(n)])
    keys.append([(-tail[j], j) for j in range(n)])
    auto = [-1] * n
    best = None
    for key in keys:
        o = build(key)
        c, st, mch = sgs(o, auto)
        if best is None or c < best[0]:
            best = (c, o, auto[:], st, mch)
    tlim = T0 + BUDGET
    try:
        t_samp = T0 + BUDGET * 0.25
        sc = cp + 1
        while time.process_time() < t_samp:
            a = rng.random() * 0.3
            kb = rng.choice(keys)
            key = [(min(kb[j][0], BIG) + rng.gauss(0, 1) * (a * sc), j) for j in range(n)]
            o = build(key)
            c, st, mch = sgs(o, auto)
            if c < best[0]:
                best = (c, o, auto[:], st, mch)
        cur_c, cur_o, cur_m = best[0], best[1][:], best[2][:]
        it = 0
        temp0 = max(1.0, best[0] * 0.02)
        tstart = time.process_time()
        while True:
            it += 1
            now = time.process_time()
            if now >= tlim:
                break
            o = cur_o[:]
            mf = cur_m[:]
            nm = 1 + (rng.random() < 0.3) + (rng.random() < 0.1)
            for _ in range(nm):
                r = rng.random()
                if r < 0.7 or n < 2:
                    pos = [0] * n
                    for q, x in enumerate(o):
                        pos[x] = q
                    i = rng.randrange(n)
                    j = o[i]
                    lo = 0
                    for p in preds[j]:
                        if pos[p] + 1 > lo:
                            lo = pos[p] + 1
                    hi = n - 1
                    for s in succs[j]:
                        if pos[s] - 1 < hi:
                            hi = pos[s] - 1
                    if hi > lo:
                        np_ = rng.randint(lo, hi)
                        if np_ != i:
                            o.pop(i)
                            o.insert(np_, j)
                else:
                    j = rng.randrange(n)
                    L = len(modes[j])
                    if L > 1:
                        mf[j] = rng.randrange(-1, L)
            c, st, mch = sgs(o, mf)
            frac = (now - tstart) / max(1e-6, tlim - tstart)
            temp = temp0 * max(0.0, 1 - frac) + 1e-9
            if c <= cur_c or rng.random() < pow(2.718281828, -(c - cur_c) / temp):
                cur_c, cur_o, cur_m = c, o, mf
                if c < best[0]:
                    best = (c, o, mf[:], st, mch)
            if it % 400 == 0 and cur_c > best[0]:
                cur_c, cur_o, cur_m = best[0], best[1][:], best[2][:]
    except Exception:
        pass
    c, o, mf, st, mch = best
    sched = {}
    for i in range(n):
        sched[ids[i]] = {"start": int(st[i]), "mode": int(modes[i][mch[i]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    state["cost"] = int(c)
    return state

import time, random, heapq

def solve(state, params):
    t0 = time.process_time()
    inp = state["input"]
    res = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    lastbp = 0
    for r in rnames:
        cal = (res[r] or {}).get("calendar") or [[0, 0]]
        cal = sorted([[int(a), int(b)] for a, b in cal])
        cals.append(cal)
        maxcap.append(max(c for _, c in cal))
        lastbp = max(lastbp, cal[-1][0])
    n = len(jobs)
    ids = [str(j["id"]) for j in jobs]
    jidx = {s: i for i, s in enumerate(ids)}
    preds = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        for p in j.get("after", []) or []:
            p = str(p)
            if p not in jidx:
                state["output"] = {"status": "infeasible",
                                   "reason": "job %s references unknown predecessor %s" % (ids[i], p)}
                return state
            preds[i].append(jidx[p])
        preds[i] = sorted(set(preds[i]))
    for i in range(n):
        if i in preds[i]:
            state["output"] = {"status": "infeasible", "reason": "precedence cycle (self-loop)"}
            return state
    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
            indeg[i] += 1
    modes = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes", []) or []):
            req = m.get("requires", {}) or {}
            ok = True
            rl = []
            for r, u in req.items():
                if r not in ridx or int(u) > maxcap[ridx[r]]:
                    ok = False
                    break
                if int(u) > 0:
                    rl.append((ridx[r], int(u)))
            if ok:
                ml.append((mi, max(1, int(m["duration"])), tuple(rl)))
        if not ml:
            state["output"] = {"status": "infeasible", "reason": "job %s has no feasible mode" % ids[i]}
            return state
        modes.append(ml)
    deg = indeg[:]
    q = [i for i in range(n) if deg[i] == 0]
    topo = []
    k = 0
    while k < len(q):
        x = q[k]
        k += 1
        topo.append(x)
        for s in succs[x]:
            deg[s] -= 1
            if deg[s] == 0:
                q.append(s)
    if len(topo) < n:
        state["output"] = {"status": "infeasible", "reason": "precedence cycle"}
        return state
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    due = [None if j.get("due") is None else int(j.get("due")) for j in jobs]
    wt = [int(j.get("weight", 0) or 0) for j in jobs]
    H = max(lastbp, max(rel)) + sum(max(d for _, d, _ in modes[i]) for i in range(n)) + 30
    base = []
    for ri in range(len(rnames)):
        arr = [0] * H
        cal = cals[ri]
        for k2 in range(len(cal)):
            a, c = cal[k2]
            b = cal[k2 + 1][0] if k2 + 1 < len(cal) else H
            a = max(0, min(a, H))
            b = min(b, H)
            for t in range(a, b):
                arr[t] = c
        base.append(arr)
    mind = [min(d for _, d, _ in modes[i]) for i in range(n)]
    tail = [0] * n
    for x in reversed(topo):
        tail[x] = mind[x] + max([tail[s] for s in succs[x]] or [0])
    head = [0] * n
    for x in topo:
        head[x] = max([rel[x]] + [head[p] + mind[p] for p in preds[x]])
    LB = max(head[x] + tail[x] for x in range(n))

    def decode(order, mvec, greedy):
        avail = [a[:] for a in base]
        fin = [0] * n
        st = [0] * n
        cm = mvec[:] if mvec is not None else [0] * n
        cost = 0
        mk = 0
        for x in order:
            e = rel[x]
            for p in preds[x]:
                if fin[p] > e:
                    e = fin[p]
            if greedy:
                cand = range(len(modes[x]))
            else:
                cand = (cm[x],)
            best = None
            for k3 in cand:
                _, dur, req = modes[x][k3]
                t = e
                while True:
                    ok = True
                    for d in range(dur):
                        td = t + d
                        for ri, u in req:
                            if avail[ri][td] < u:
                                ok = False
                                break
                        if not ok:
                            t = td + 1
                            break
                    if ok:
                        break
                f = t + dur
                sc = f
                if due[x] is not None and f > due[x]:
                    sc += wt[x] * (f - due[x])
                sc2 = (sc, sum(u * dur for _, u in req))
                if best is None or sc2 < best[0]:
                    best = (sc2, k3, t, dur, req)
            _, k3, t, dur, req = best
            cm[x] = k3
            for ri, u in req:
                a = avail[ri]
                for td in range(t, t + dur):
                    a[td] -= u
            st[x] = t
            f = t + dur
            fin[x] = f
            if f > mk:
                mk = f
            if due[x] is not None and f > due[x]:
                cost += wt[x] * (f - due[x])
        return cost + mk, st, cm, fin

    rng = random.Random(12345)

    def prio_order(key):
        dg = indeg[:]
        h = [(key[i], i) for i in range(n) if dg[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                dg[s] -= 1
                if dg[s] == 0:
                    heapq.heappush(h, (key[s], s))
        return out

    big = LB * 4 + 1000
    keys = []
    keys.append([-tail[i] for i in range(n)])
    keys.append([head[i] - tail[i] for i in range(n)])
    keys.append([(due[i] - tail[i]) if due[i] is not None else big - tail[i] for i in range(n)])
    keys.append([min(LB - tail[i], (due[i] - tail[i] + mind[i]) if (due[i] is not None and wt[i] > 0) else big)
                 for i in range(n)])
    keys.append([head[i] for i in range(n)])
    budget = 0.80
    best = None

    def consider(r, order):
        nonlocal best
        if best is None or r[0] < best[0]:
            best = (r[0], list(order), r[2][:], r[1][:])

    for key in keys:
        o = prio_order(key)
        consider(decode(o, None, True), o)

    phase1 = t0 + budget * 0.3
    noise = max(2.0, 0.2 * LB)
    it = 0
    while time.process_time() < phase1 and best[0] > LB:
        key = keys[it % len(keys)]
        noisy = [key[i] + rng.random() * noise for i in range(n)]
        o = prio_order(noisy)
        consider(decode(o, None, True), o)
        it += 1

    cur = (best[0], best[1][:], best[2][:])
    pos = [0] * n
    deadline = t0 + budget
    stall = 0
    while time.process_time() < deadline and best[0] > LB:
        order = cur[1][:]
        mv = cur[2][:]
        nm = 1 + (rng.random() < 0.3) + (rng.random() < 0.1)
        for _ in range(nm):
            if rng.random() < 0.25:
                x = rng.randrange(n)
                if len(modes[x]) > 1:
                    mv[x] = rng.randrange(len(modes[x]))
                    continue
            for i2, x in enumerate(order):
                pos[x] = i2
            i = rng.randrange(n)
            x = order[i]
            lo = max([pos[p] for p in preds[x]] or [-1]) + 1
            hi = min([pos[s] for s in succs[x]] or [n]) - 1
            if hi <= lo:
                continue
            jpos = rng.randint(lo, hi)
            if jpos == i:
                continue
            order.pop(i)
            order.insert(jpos, x)
        greedy = rng.random() < 0.2
        r = decode(order, mv, greedy)
        if r[0] <= cur[0]:
            if r[0] < cur[0]:
                stall = 0
            else:
                stall += 1
            cur = (r[0], order, r[2])
            consider(r, order)
        else:
            stall += 1
        if stall > 300:
            cur = (best[0], best[1][:], best[2][:])
            stall = 0

    _, order, cm, st = best
    sched = {}
    for i in range(n):
        sched[ids[i]] = {"start": int(st[i]), "mode": int(modes[i][cm[i]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    return state

import time, random, heapq

def solve(state, params):
    T0 = time.process_time()
    DEADLINE = T0 + 0.72
    inp = state.get("input") or {}
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(res.keys())
    ridx = {nm: i for i, nm in enumerate(rnames)}
    cals = []
    maxcap = []
    for nm in rnames:
        cal = (res[nm] or {}).get("calendar") or [[0, 0]]
        cal = sorted([[int(a), int(b)] for a, b in cal], key=lambda x: x[0])
        cals.append(cal)
        maxcap.append(cal[-1][1])
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    ids = [str(j["id"]) for j in jobs]
    idx = {}
    for i, s in enumerate(ids):
        idx[s] = i

    def infeasible(msg):
        state["output"] = {"status": "infeasible", "reason": msg}
        return state

    preds = []
    for j in jobs:
        ps = []
        for p in (j.get("after") or []):
            p = str(p)
            if p not in idx:
                return infeasible("job %s references unknown predecessor %s" % (j["id"], p))
            q = idx[p]
            if q not in ps:
                ps.append(q)
        preds.append(ps)
    modes = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes") or []):
            d = int(m.get("duration", 1))
            reqs = []
            ok = True
            for rn, u in (m.get("requires") or {}).items():
                u = int(u)
                if u <= 0:
                    continue
                if rn not in ridx or u > maxcap[ridx[rn]]:
                    ok = False
                    break
                reqs.append((ridx[rn], u))
            if ok and d >= 0:
                ml.append((mi, d, reqs))
        if not ml:
            return infeasible("job %s has no feasible mode" % ids[i])
        modes.append(ml)
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]
    topo = []
    while q:
        x = q.pop()
        topo.append(x)
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    if len(topo) < n:
        return infeasible("precedence cycle")

    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    due = [j.get("due") for j in jobs]
    wt = [int(j.get("weight", 0) or 0) for j in jobs]
    hasdue = [due[i] is not None and wt[i] > 0 for i in range(n)]
    dueI = [int(due[i]) if due[i] is not None else 0 for i in range(n)]
    R = len(rnames)
    lastbp = max([c[-1][0] for c in cals] + [0])
    H = max(lastbp, max(rel)) + sum(max(m[1] for m in ml) for ml in modes) + 20
    base = []
    for r in range(R):
        cal = cals[r]
        arr = [0] * H
        for k in range(len(cal)):
            a = cal[k][0]
            b = cal[k + 1][0] if k + 1 < len(cal) else H
            if a >= H:
                break
            b = min(b, H)
            cap = cal[k][1]
            for t in range(max(a, 0), b):
                arr[t] = cap
        base.append(arr)
    mload = []
    for ml in modes:
        mload.append([sum(u * d / max(1, maxcap[r]) for r, u in reqs) for (_, d, reqs) in ml])
    mind = [min(m[1] for m in ml) for ml in modes]

    def find(avail, t, d, reqs):
        while True:
            moved = False
            for r, u in reqs:
                a = avail[r]
                if t + d > len(a):
                    for rr in range(R):
                        avail[rr].extend([maxcap[rr]] * (t + d + 50 - len(avail[rr])))
                    a = avail[r]
                k = t + d - 1
                while k >= t:
                    if a[k] < u:
                        break
                    k -= 1
                if k >= t:
                    t = k + 1
                    moved = True
                    break
            if not moved:
                return t

    def decode(order, fixed, lam):
        avail = [b[:] for b in base]
        start = [0] * n
        fin = [0] * n
        mch = [0] * n
        tard = 0
        for j in order:
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            ml = modes[j]
            if fixed is not None:
                cand = (fixed[j],)
            else:
                cand = range(len(ml))
            bs = None
            bt = est
            bm = 0
            for mi in cand:
                _, d, reqs = ml[mi]
                t = find(avail, est, d, reqs)
                f = t + d
                sc = f
                if hasdue[j] and f > dueI[j]:
                    sc += wt[j] * (f - dueI[j])
                if lam:
                    sc += lam * mload[j][mi]
                if bs is None or sc < bs:
                    bs = sc
                    bt = t
                    bm = mi
            _, d, reqs = ml[bm]
            for r, u in reqs:
                a = avail[r]
                for k in range(bt, bt + d):
                    a[k] -= u
            start[j] = bt
            fin[j] = bt + d
            mch[j] = bm
            if hasdue[j] and bt + d > dueI[j]:
                tard += wt[j] * (bt + d - dueI[j])
        cost = max(fin) + tard
        return cost, start, mch

    ef = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            if ef[p] > e:
                e = ef[p]
        ef[j] = e + mind[j]
    Tcp = max(ef)
    lf = [Tcp] * n
    for j in reversed(topo):
        v = lf[j]
        if hasdue[j] and dueI[j] < v:
            v = dueI[j]
        for s in succs[j]:
            x = lf[s] - mind[s]
            if x < v:
                v = x
        lf[j] = v
    lst = [lf[j] - mind[j] for j in range(n)]
    nsucc = [0.0] * n
    for j in reversed(topo):
        nsucc[j] = min(1e9, len(succs[j]) + sum(nsucc[s] for s in succs[j]) * 0.5)
    estv = [ef[j] - mind[j] for j in range(n)]
    span = max(1, Tcp)

    def build(key):
        dg = [len(preds[i]) for i in range(n)]
        h = [(key[i], i) for i in range(n) if dg[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                dg[s] -= 1
                if dg[s] == 0:
                    heapq.heappush(h, (key[s], s))
        return out

    rng = random.Random(12345)
    best = None

    def norm(start, order):
        pos = {}
        for k, j in enumerate(order):
            pos[j] = k
        return sorted(range(n), key=lambda j: (start[j], pos[j]))

    def consider(cost, start, mch, order):
        nonlocal best
        if best is None or cost < best[0]:
            best = (cost, norm(start, order), list(mch), list(start))

    keys = [
        [lst[j] for j in range(n)],
        [lf[j] for j in range(n)],
        [estv[j] for j in range(n)],
        [lst[j] - 0.01 * nsucc[j] for j in range(n)],
        [-nsucc[j] for j in range(n)],
        [rel[j] + 0.001 * lst[j] for j in range(n)],
    ]
    lams = [0, 0.5, 2.0]
    for key in keys:
        o = build(key)
        for lam in lams:
            c, s, m = decode(o, None, lam)
            consider(c, s, m, o)
        if time.process_time() > DEADLINE:
            break

    phase1 = T0 + 0.30 * (DEADLINE - T0)
    while time.process_time() < phase1:
        noise = rng.choice([0.05, 0.15, 0.4])
        base_key = keys[rng.randrange(4)]
        key = [base_key[j] + rng.random() * noise * span for j in range(n)]
        o = build(key)
        c, s, m = decode(o, None, rng.choice(lams))
        consider(c, s, m, o)

    cur_cost, cur_order, cur_m = best[0], list(best[1]), list(best[2])
    multi = [j for j in range(n) if len(modes[j]) > 1]
    stall = 0
    while time.process_time() < DEADLINE:
        order = cur_order
        fixed = cur_m
        r = rng.random()
        if multi and r < 0.3:
            fixed = list(cur_m)
            j = rng.choice(multi)
            mi = rng.randrange(len(modes[j]) - 1)
            if mi >= fixed[j]:
                mi += 1
            fixed[j] = mi
            if rng.random() < 0.3:
                j2 = rng.choice(multi)
                fixed[j2] = rng.randrange(len(modes[j2]))
        elif r < 0.37:
            fixed = None
        else:
            nm = 1 if rng.random() < 0.7 else rng.randint(2, 4)
            order = list(cur_order)
            for _ in range(nm):
                pos = [0] * n
                for k, x in enumerate(order):
                    pos[x] = k
                j = rng.randrange(n)
                i = pos[j]
                lo = 0
                for p in preds[j]:
                    if pos[p] + 1 > lo:
                        lo = pos[p] + 1
                hi = n - 1
                for s in succs[j]:
                    if pos[s] - 1 < hi:
                        hi = pos[s] - 1
                if hi <= lo:
                    continue
                if rng.random() < 0.6:
                    np_ = max(lo, min(hi, i + rng.randint(-6, 6)))
                else:
                    np_ = rng.randint(lo, hi)
                if np_ == i:
                    continue
                order.pop(i)
                order.insert(np_, j)
        c, s, m = decode(order, fixed, rng.choice(lams) if fixed is None else 0)
        if c <= cur_cost or (stall > 60 and c <= cur_cost * 1.02):
            if c < cur_cost:
                stall = 0
            else:
                stall += 1
            cur_cost = c
            cur_order = norm(s, order)
            cur_m = list(m)
            consider(c, s, m, order)
            if stall > 60:
                stall = 0
        else:
            stall += 1
        if stall > 400:
            stall = 0
            cur_cost, cur_order, cur_m = best[0], list(best[1]), list(best[2])

    _, _, mch, start = best
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": int(start[j]), "mode": int(modes[j][mch[j]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    return state

import time, random, math, heapq

def solve(state, params):
    t_start = time.process_time()
    BUDGET = 0.72
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs_in = inp.get("jobs") or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    R = len(rnames)
    cals = []
    maxcap = []
    lastbp = 0
    for r in rnames:
        cal = (resources[r] or {}).get("calendar") or [[0, 0]]
        cal = sorted([(int(a), int(b)) for a, b in cal])
        cals.append(cal)
        maxcap.append(max(b for a, b in cal))
        lastbp = max(lastbp, cal[-1][0])
    n = len(jobs_in)
    ids = [str(j.get("id")) for j in jobs_in]
    pos = {}
    for i, x in enumerate(ids):
        pos[x] = i
    preds = []
    for i, j in enumerate(jobs_in):
        pl = []
        for p in (j.get("after") or []):
            p = str(p)
            if p not in pos:
                state["output"] = {"status": "infeasible", "reason": "job %s references unknown predecessor %s" % (ids[i], p)}
                return state
            q = pos[p]
            if q not in pl:
                pl.append(q)
        preds.append(pl)
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    topo = [i for i in range(n) if indeg[i] == 0]
    k = 0
    while k < len(topo):
        u = topo[k]; k += 1
        for s in succs[u]:
            indeg[s] -= 1
            if indeg[s] == 0:
                topo.append(s)
    if len(topo) < n:
        state["output"] = {"status": "infeasible", "reason": "precedence cycle"}
        return state
    rel = []; due = []; wt = []; modes = []
    for i, j in enumerate(jobs_in):
        rel.append(max(0, int(j.get("release") or 0)))
        d = j.get("due")
        due.append(None if d is None else int(d))
        wt.append(int(j.get("weight") or 0))
        ml = []
        for mi, m in enumerate(j.get("modes") or []):
            dur = int(m.get("duration", 1))
            req = m.get("requires") or {}
            ok = True; rl = []
            for rn, u in req.items():
                u = int(u)
                if rn not in ridx or u > maxcap[ridx[rn]]:
                    ok = False; break
                if u > 0:
                    rl.append((ridx[rn], u))
            if ok:
                ml.append((dur, tuple(rl), mi))
        keep = []
        for a in ml:
            da = dict((r, u) for r, u in a[1])
            dom = False
            for b in ml:
                if b is a:
                    continue
                db = dict((r, u) for r, u in b[1])
                if b[0] <= a[0] and all(db.get(r, 0) <= da.get(r, 0) for r in db):
                    if b[0] < a[0] or any(db.get(r, 0) < da.get(r, 0) for r in da) or b[2] < a[2]:
                        dom = True; break
            if not dom:
                keep.append(a)
        if not keep:
            state["output"] = {"status": "infeasible", "reason": "job %s has no mode fitting the resources" % ids[i]}
            return state
        modes.append(keep)
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    maxd = [max(m[0] for m in modes[i]) for i in range(n)]
    mind = [min(m[0] for m in modes[i]) for i in range(n)]
    H = max(lastbp, max(rel)) + sum(maxd) + 30
    base = []
    for r in range(R):
        cal = cals[r]
        arr = [0] * H
        for k2 in range(len(cal)):
            a = cal[k2][0]; b = cal[k2+1][0] if k2 + 1 < len(cal) else H
            c = cal[k2][1]
            for t in range(max(0, a), min(b, H)):
                arr[t] = c
        base.append(arr)
    wnorm = [1.0 / max(1, maxcap[r]) for r in range(R)]

    def earliest(avail, t, d, rl):
        lim = H - d
        while t <= lim:
            ok = True
            for r, u in rl:
                a = avail[r]
                for s in range(t, t + d):
                    if a[s] < u:
                        t = s + 1; ok = False; break
                if not ok:
                    break
            if ok:
                return t
        return -1

    def decode(order, mlist, alpha):
        avail = [a[:] for a in base]
        st = [0] * n; fin = [0] * n; mo = [0] * n
        for j in order:
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            ms = modes[j]
            if mlist is not None and mlist[j] >= 0:
                mk = mlist[j]
                dur, rl, _ = ms[mk]
                s = earliest(avail, est, dur, rl)
                if s < 0:
                    return None
            else:
                best = None
                dj = due[j]; w = wt[j]
                for mk2 in range(len(ms)):
                    dur2, rl2, _ = ms[mk2]
                    s2 = earliest(avail, est, dur2, rl2)
                    if s2 < 0:
                        continue
                    f2 = s2 + dur2
                    sc = f2
                    if dj is not None and f2 > dj:
                        sc += w * (f2 - dj)
                    usage = dur2 * sum(u * wnorm[r] for r, u in rl2)
                    if alpha:
                        sc += alpha * usage
                    key = (sc, f2, usage)
                    if best is None or key < best[0]:
                        best = (key, mk2, s2)
                if best is None:
                    return None
                mk = best[1]; s = best[2]
                dur, rl, _ = ms[mk]
            for r, u in rl:
                a = avail[r]
                for t in range(s, s + dur):
                    a[t] -= u
            st[j] = s; fin[j] = s + dur; mo[j] = mk
        cost = max(fin)
        for j in range(n):
            if due[j] is not None and fin[j] > due[j]:
                cost += wt[j] * (fin[j] - due[j])
        return (cost, st, mo, fin)

    def plist(key):
        indeg2 = [len(preds[i]) for i in range(n)]
        h = [(key[i], i) for i in range(n) if indeg2[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, u = heapq.heappop(h)
            out.append(u)
            for s in succs[u]:
                indeg2[s] -= 1
                if indeg2[s] == 0:
                    heapq.heappush(h, (key[s], s))
        return out

    def fbi(sol):
        cost, st, mo, fin = sol
        T = max(fin)
        avail = [a[:] for a in base]
        order = sorted(range(n), key=lambda j: (-fin[j], -st[j]))
        bst = [0] * n
        for j in order:
            dur, rl, _ = modes[j][mo[j]]
            lf = T
            for s2 in succs[j]:
                if bst[s2] < lf:
                    lf = bst[s2]
            s = lf - dur
            while s >= rel[j]:
                ok = True
                for r, u in rl:
                    a = avail[r]
                    for t in range(s + dur - 1, s - 1, -1):
                        if a[t] < u:
                            s = t - dur; ok = False; break
                    if not ok:
                        break
                if ok:
                    break
            if s < rel[j]:
                s = st[j]
            for r, u in rl:
                a = avail[r]
                for t in range(s, s + dur):
                    a[t] -= u
            bst[j] = s
        order2 = plist([(bst[j], -len(succs[j])) for j in range(n)])
        res = decode(order2, mo, 0)
        return res, order2

    tail = [0] * n
    for u in reversed(topo):
        tl = 0
        for s in succs[u]:
            if tail[s] > tl:
                tl = tail[s]
        tail[u] = tl + mind[u]
    BIG = 10 ** 9
    dl = [BIG] * n
    for u in reversed(topo):
        d = due[u] if (due[u] is not None and wt[u] > 0) else BIG
        for s in succs[u]:
            if dl[s] < BIG and dl[s] - mind[s] < d:
                d = dl[s] - mind[s]
        dl[u] = d
    head = [0] * n
    for u in topo:
        h0 = rel[u]
        for p in preds[u]:
            if head[p] + mind[p] > h0:
                h0 = head[p] + mind[p]
        head[u] = h0
    UB = H
    rnd = random.Random(12345)
    keys = []
    keys.append([-tail[i] for i in range(n)])
    keys.append([(min(dl[i], UB), -tail[i]) for i in range(n)])
    keys.append([(head[i], -tail[i]) for i in range(n)])
    keys.append([min(dl[i] - tail[i], UB - tail[i]) for i in range(n)])
    keys.append([(dl[i] if dl[i] < BIG else BIG, -wt[i], -tail[i]) for i in range(n)])
    keys.append([head[i] - tail[i] for i in range(n)])

    def elapsed():
        return time.process_time() - t_start

    best = None; bestorder = None
    cands = []
    for key in keys:
        o = plist(key)
        for alpha in (0, 0.5):
            r = decode(o, None, alpha)
            if r is not None:
                cands.append((r[0], o, r))
                if best is None or r[0] < best[0]:
                    best = r; bestorder = o
        if elapsed() > BUDGET * 0.3:
            break
    cands.sort(key=lambda x: x[0])
    for c, o, r in cands[:4]:
        if elapsed() > BUDGET * 0.4:
            break
        cur = r; curo = o
        for _ in range(3):
            r2, o2 = fbi(cur)
            if r2 is None or r2[0] >= cur[0]:
                if r2 is not None and r2[0] == cur[0]:
                    cur, curo = r2, o2
                break
            cur, curo = r2, o2
        if cur[0] < best[0]:
            best = cur; bestorder = curo

    cur = best; curo = list(bestorder); curm = list(best[2])
    posi = [0] * n
    T0 = max(1.0, 0.03 * best[0])
    it = 0
    since = 0
    multi = [j for j in range(n) if len(modes[j]) > 1]
    while True:
        it += 1
        if (it & 3) == 0 and elapsed() > BUDGET:
            break
        frac = elapsed() / BUDGET
        temp = T0 * max(0.0, 1.0 - frac) + 0.01
        newo = curo; newm = curm
        mv = rnd.random()
        if multi and mv < 0.3:
            newm = list(curm)
            j = rnd.choice(multi)
            m2 = rnd.randrange(len(modes[j]) - 1)
            if m2 >= curm[j]:
                m2 += 1
            newm[j] = m2
            if rnd.random() < 0.3:
                j = rnd.choice(multi)
                newm[j] = rnd.randrange(len(modes[j]))
        else:
            newo = list(curo)
            nm = 1 if rnd.random() < 0.8 else 2
            for _ in range(nm):
                for i2, j in enumerate(newo):
                    posi[j] = i2
                p = rnd.randrange(n)
                j = newo[p]
                lo = 0
                for q in preds[j]:
                    if posi[q] + 1 > lo:
                        lo = posi[q] + 1
                hi = n - 1
                for q in succs[j]:
                    if posi[q] - 1 < hi:
                        hi = posi[q] - 1
                if hi <= lo:
                    continue
                np_ = rnd.randint(lo, hi)
                if np_ == p:
                    continue
                del newo[p]
                newo.insert(np_, j)
        res = decode(newo, newm, 0)
        if res is None:
            continue
        d = res[0] - cur[0]
        if d <= 0 or rnd.random() < math.exp(-d / temp):
            cur = res; curo = newo; curm = list(res[2])
            if res[0] < best[0]:
                best = res; bestorder = newo; since = 0
            if d < 0 and rnd.random() < 0.5 and elapsed() < BUDGET:
                r2, o2 = fbi(cur)
                if r2 is not None and r2[0] <= cur[0]:
                    cur = r2; curo = o2; curm = list(r2[2])
                    if r2[0] < best[0]:
                        best = r2; bestorder = o2; since = 0
        since += 1
        if since > 400:
            cur = best; curo = list(bestorder); curm = list(best[2]); since = 0
    cost, st, mo, fin = best
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": int(st[j]), "mode": int(modes[j][mo[j]][2])}
    state["output"] = {"status": "ok", "schedule": sched}
    state["iters"] = it
    state["cost"] = cost
    return state

import time, random, heapq


def _fail(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def solve(state, params):
    T0 = time.process_time()
    BUDGET = 0.72
    inp = state["input"]
    resources = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    n = len(jobs)
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    lastbp = 0
    for r in rnames:
        cal = resources[r].get("calendar", [[0, 0]]) or [[0, 0]]
        cal = sorted([(int(a), int(b)) for a, b in cal])
        cals.append(cal)
        maxcap.append(max(cal[-1][1], 0))
        lastbp = max(lastbp, cal[-1][0])
    ids = [str(j["id"]) for j in jobs]
    jidx = {}
    for i, s in enumerate(ids):
        jidx[s] = i
    preds = []
    for j in jobs:
        pl = []
        for p in j.get("after", []) or []:
            if str(p) not in jidx:
                return _fail(state, "unknown predecessor %s" % p)
            pl.append(jidx[str(p)])
        preds.append(sorted(set(pl)))
    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
            indeg[i] += 1
    topo = []
    dq = [i for i in range(n) if indeg[i] == 0]
    deg = indeg[:]
    while dq:
        x = dq.pop()
        topo.append(x)
        for s in succs[x]:
            deg[s] -= 1
            if deg[s] == 0:
                dq.append(s)
    if len(topo) < n:
        return _fail(state, "precedence cycle")
    fmodes = []
    for i, j in enumerate(jobs):
        ml = []
        for k, m in enumerate(j.get("modes", []) or []):
            d = int(m["duration"])
            ok = True
            reqs = []
            work = 0.0
            for r, u in (m.get("requires", {}) or {}).items():
                u = int(u)
                if r not in ridx:
                    ok = False
                    break
                if u <= 0:
                    continue
                if u > maxcap[ridx[r]]:
                    ok = False
                    break
                reqs.append((ridx[r], u))
                work += d * u / float(maxcap[ridx[r]])
            if ok:
                ml.append((d, tuple(reqs), k, work))
        if not ml:
            return _fail(state, "job %s has no feasible mode" % ids[i])
        fmodes.append(ml)
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    due = [j.get("due") for j in jobs]
    w = [int(j.get("weight", 0) or 0) for j in jobs]
    hasdue = [due[i] is not None and w[i] > 0 for i in range(n)]
    dueI = [int(due[i]) if due[i] is not None else 0 for i in range(n)]
    H = lastbp + max(rel + [0]) + sum(max(m[0] for m in fm) for fm in fmodes) + 30
    base = []
    for c in cals:
        arr = [0] * H
        for k in range(len(c)):
            a = c[k][0]
            b = c[k + 1][0] if k + 1 < len(c) else H
            cap = max(c[k][1], 0)
            for t in range(max(a, 0), min(b, H)):
                arr[t] = cap
        base.append(arr)
    R = len(base)
    mind = [min(m[0] for m in fm) for fm in fmodes]

    def decode(order, mfix, policy):
        av = [a[:] for a in base]
        st = [0] * n
        fin = [0] * n
        md = [0] * n
        cost = 0
        mk = 0
        for j in order:
            t0 = rel[j]
            for p in preds[j]:
                if fin[p] > t0:
                    t0 = fin[p]
            fm = fmodes[j]
            cands = fm if mfix is None else (fm[mfix[j]],)
            best = None
            bk = None
            for mi in range(len(cands)):
                d, reqs, _, wk = cands[mi]
                t = t0
                if reqs:
                    while True:
                        e = t + d
                        moved = False
                        for (r, u) in reqs:
                            if e > len(av[r]):
                                for q in range(R):
                                    if e + 50 > len(av[q]):
                                        av[q].extend([maxcap[q]] * (e + 50 - len(av[q])))
                            a = av[r]
                            tau = e - 1
                            while tau >= t:
                                if a[tau] < u:
                                    break
                                tau -= 1
                            if tau >= t:
                                t = tau + 1
                                moved = True
                                break
                        if not moved:
                            break
                f = t + d
                if mfix is None:
                    tc = f + (w[j] * (f - dueI[j]) if hasdue[j] and f > dueI[j] else 0)
                    if policy == 0:
                        key = (tc, wk)
                    elif policy == 1:
                        key = (tc + 0.5 * wk, wk)
                    else:
                        key = (wk, tc)
                    if bk is None or key < bk:
                        bk = key
                        best = (t, mi)
                else:
                    best = (t, mfix[j])
            t, mi = best
            d, reqs, _, _ = fm[mi]
            for (r, u) in reqs:
                a = av[r]
                for tau in range(t, t + d):
                    a[tau] -= u
            st[j] = t
            f = t + d
            fin[j] = f
            md[j] = mi
            if f > mk:
                mk = f
            if hasdue[j] and f > dueI[j]:
                cost += w[j] * (f - dueI[j])
        return cost + mk, st, md

    tail = [0] * n
    for j in reversed(topo):
        tl = 0
        for s in succs[j]:
            if tail[s] > tl:
                tl = tail[s]
        tail[j] = tl + mind[j]
    est = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            if est[p] + mind[p] > e:
                e = est[p] + mind[p]
        est[j] = e
    CP = max([est[j] + tail[j] for j in range(n)] + [1])
    lfd = [0] * n
    for j in reversed(topo):
        v = CP
        if hasdue[j]:
            v = min(v, dueI[j])
        for s in succs[j]:
            v = min(v, lfd[s] - mind[s])
        lfd[j] = v
    wsum = [0] * n
    for j in reversed(topo):
        v = w[j] if hasdue[j] else 0
        for s in succs[j]:
            v += wsum[s]
        wsum[j] = v
    rules = [
        [CP - tail[j] for j in range(n)],
        [lfd[j] - mind[j] for j in range(n)],
        [lfd[j] - mind[j] - 0.3 * wsum[j] for j in range(n)],
        [est[j] for j in range(n)],
        [est[j] + 0.5 * (CP - tail[j]) for j in range(n)],
        [-len(succs[j]) for j in range(n)],
        [min(lfd[j], CP - tail[j] + mind[j]) - mind[j] for j in range(n)],
    ]

    def make_order(key):
        dg = indeg[:]
        h = [(key[i], i) for i in range(n) if dg[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                dg[s] -= 1
                if dg[s] == 0:
                    heapq.heappush(h, (key[s], s))
        return out

    rng = random.Random(12345 + n)
    best = None

    def consider(cost, order, md):
        nonlocal best
        if best is None or cost < best[0]:
            best = (cost, order[:], md[:])

    def tleft():
        return BUDGET - (time.process_time() - T0)

    for key in rules:
        order = make_order(key)
        for pol in (0, 1, 2):
            c, st, md = decode(order, None, pol)
            consider(c, order, md)
        if tleft() < BUDGET * 0.6:
            break
    spread = max(CP, 1)
    ns = 0
    while tleft() > BUDGET * 0.65 and ns < 40:
        key = rules[rng.randrange(len(rules))]
        noise = rng.choice((0.05, 0.15, 0.3))
        k2 = [key[i] + rng.random() * noise * spread for i in range(n)]
        order = make_order(k2)
        c, st, md = decode(order, None, rng.randrange(2))
        consider(c, order, md)
        ns += 1

    cur_c, cur_o, cur_m = best[0], best[1][:], best[2][:]
    multi = [j for j in range(n) if len(fmodes[j]) > 1]
    stall = 0
    while n > 1 and tleft() > 0.01:
        o = cur_o[:]
        m = cur_m[:]
        nm = 1 if stall < 60 else rng.randint(2, 5)
        for _ in range(nm):
            mv = rng.random()
            if multi and mv < 0.3:
                j = rng.choice(multi)
                k = rng.randrange(len(fmodes[j]) - 1)
                if k >= m[j]:
                    k += 1
                m[j] = k
            else:
                p = rng.randrange(n)
                j = o[p]
                pos = {x: i for i, x in enumerate(o)}
                lo = 0
                for q in preds[j]:
                    if pos[q] + 1 > lo:
                        lo = pos[q] + 1
                hi = n - 1
                for s in succs[j]:
                    if pos[s] - 1 < hi:
                        hi = pos[s] - 1
                if hi <= lo:
                    continue
                np_ = rng.randint(lo, hi)
                if np_ == p:
                    continue
                o.pop(p)
                o.insert(np_, j)
        c, st, md = decode(o, m, 0)
        if c <= cur_c:
            if c < cur_c:
                stall = 0
            else:
                stall += 1
            cur_c, cur_o, cur_m = c, o, m
            consider(c, o, m)
        else:
            stall += 1
            if stall > 250:
                cur_c, cur_o, cur_m = best[0], best[1][:], best[2][:]
                stall = 0
    c, st, md = decode(best[1], best[2], 0)
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": int(st[j]), "mode": int(fmodes[j][md[j]][2])}
    state["output"] = {"status": "ok", "schedule": sched}
    return state

import time
import random
import heapq


def solve(state, params):
    T0 = time.process_time()
    BUD = 0.78

    def tl():
        return time.process_time() - T0

    inp = state.get("input") or {}
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []

    def infeasible(msg):
        state["output"] = {"status": "infeasible", "reason": msg}
        return state

    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    lastbp = 0
    for r in rnames:
        rd = res[r] or {}
        cal = rd.get("calendar") or [[0, 0]]
        cal = sorted([(int(a[0]), int(a[1])) for a in cal])
        if not cal:
            cal = [(0, 0)]
        cals.append(cal)
        maxcap.append(cal[-1][1])
        if cal[-1][0] > lastbp:
            lastbp = cal[-1][0]
    R = len(rnames)

    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state

    ids = [str(jb.get("id")) for jb in jobs]
    idm = {}
    for i, x in enumerate(ids):
        idm[x] = i

    preds = [[] for _ in range(n)]
    succs = [[] for _ in range(n)]
    for i, jb in enumerate(jobs):
        seen = set()
        for p in (jb.get("after") or []):
            p = str(p)
            if p not in idm:
                return infeasible("job %s references unknown predecessor %s" % (ids[i], p))
            q = idm[p]
            if q == i:
                return infeasible("precedence cycle (self-loop at %s)" % ids[i])
            if q in seen:
                continue
            seen.add(q)
            preds[i].append(q)
            succs[q].append(i)

    jmodes = []
    rel = []
    due = []
    wt = []
    for i, jb in enumerate(jobs):
        ml = []
        for k, m in enumerate(jb.get("modes") or []):
            d = int(m.get("duration", 1))
            if d < 1:
                d = 1
            req = m.get("requires") or {}
            ok = True
            rl = []
            area = 0.0
            for rn, u in req.items():
                u = int(u)
                if rn not in ridx:
                    ok = False
                    break
                ri = ridx[rn]
                if u > maxcap[ri]:
                    ok = False
                    break
                if u > 0:
                    rl.append((ri, u))
                    area += float(u) / max(1, maxcap[ri])
            if ok:
                ml.append((d, tuple(rl), area * d, k))
        if not ml:
            return infeasible("job %s has no executable mode" % ids[i])
        jmodes.append(ml)
        rel.append(max(0, int(jb.get("release", 0) or 0)))
        dd = jb.get("due")
        due.append(None if dd is None else int(dd))
        wt.append(int(jb.get("weight", 0) or 0))

    # cycle check / topological order
    indeg = [len(preds[j]) for j in range(n)]
    stack = [j for j in range(n) if indeg[j] == 0]
    topo = []
    while stack:
        j = stack.pop()
        topo.append(j)
        for s in succs[j]:
            indeg[s] -= 1
            if indeg[s] == 0:
                stack.append(s)
    if len(topo) < n:
        return infeasible("precedence relation has a cycle")

    dued = [j for j in range(n) if due[j] is not None and wt[j] > 0]

    maxrel = max(rel)
    sumd = sum(max(m[0] for m in jmodes[j]) for j in range(n))
    H = max(maxrel, lastbp) + sumd + 30
    base = []
    for ri in range(R):
        cal = cals[ri]
        arr = [0] * H
        for i, (a, c) in enumerate(cal):
            b = cal[i + 1][0] if i + 1 < len(cal) else H
            a = max(a, 0)
            b = min(b, H)
            if b > a:
                arr[a:b] = [c] * (b - a)
        base.append(arr)

    # priority information
    mind = [min(m[0] for m in jmodes[j]) for j in range(n)]
    es = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            v = es[p] + mind[p]
            if v > e:
                e = v
        es[j] = e
    tail = [0] * n
    INF = float("inf")
    lf = [INF] * n
    for j in reversed(topo):
        t = 0
        for s in succs[j]:
            if tail[s] > t:
                t = tail[s]
        tail[j] = t + mind[j]
        v = INF if due[j] is None else float(due[j])
        for s in succs[j]:
            w = lf[s] - mind[s]
            if w < v:
                v = w
        lf[j] = v
    CP = max(es[j] + tail[j] for j in range(n))
    lst_cp = [float(CP - tail[j]) for j in range(n)]
    lsd = [lf[j] - mind[j] for j in range(n)]

    keys = []
    keys.append([min(lst_cp[j], lsd[j]) for j in range(n)])
    keys.append([min(lst_cp[j], lsd[j] - 2.0 * wt[j]) for j in range(n)])
    keys.append(lst_cp[:])
    keys.append([float(es[j]) + 0.001 * lst_cp[j] for j in range(n)])
    keys.append([-float(tail[j]) for j in range(n)])

    def build(key):
        dg = [len(preds[j]) for j in range(n)]
        hp = [(key[j], j) for j in range(n) if dg[j] == 0]
        heapq.heapify(hp)
        out = []
        while hp:
            _, j = heapq.heappop(hp)
            out.append(j)
            for s in succs[j]:
                dg[s] -= 1
                if dg[s] == 0:
                    heapq.heappush(hp, (key[s], s))
        return out

    def decode(order, msel):
        av = [a[:] for a in base]
        st = [0] * n
        fn = [0] * n
        md = [0] * n
        for j in order:
            e = rel[j]
            for p in preds[j]:
                f = fn[p]
                if f > e:
                    e = f
            jm = jmodes[j]
            s = msel[j]
            cand = (s,) if s >= 0 else range(len(jm))
            bk = None
            bt = 0
            bkk = 0
            for k in cand:
                d, req, area, _ = jm[k]
                if bk is not None and e + d > bk[0]:
                    continue
                t = e
                if req:
                    while True:
                        end = t + d
                        bad = t - 1
                        for r, u in req:
                            a = av[r]
                            tau = end - 1
                            while tau >= t and a[tau] >= u:
                                tau -= 1
                            if tau > bad:
                                bad = tau
                        if bad < t:
                            break
                        t = bad + 1
                key = (t + d, area)
                if bk is None or key < bk:
                    bk = key
                    bt = t
                    bkk = k
            d, req, _, _ = jm[bkk]
            for r, u in req:
                a = av[r]
                for tau in range(bt, bt + d):
                    a[tau] -= u
            st[j] = bt
            fn[j] = bt + d
            md[j] = bkk
        cost = max(fn)
        for j in dued:
            if fn[j] > due[j]:
                cost += wt[j] * (fn[j] - due[j])
        return [cost, st, fn, md, av]

    def fbi(r0):
        _, st, fn, md, av = r0
        av = [a[:] for a in av]
        Cmax = max(fn)
        ns = st[:]
        ordr = sorted(range(n), key=lambda j: -fn[j])
        for j in ordr:
            d, req, _, _ = jmodes[j][md[j]]
            lim = Cmax - d
            for s in succs[j]:
                v = ns[s] - d
                if v < lim:
                    lim = v
            s0 = ns[j]
            if lim <= s0:
                continue
            if not req:
                ns[j] = lim
                continue
            for r, u in req:
                a = av[r]
                for tau in range(s0, s0 + d):
                    a[tau] += u
            t = lim
            while t > s0:
                end = t + d
                mt = end
                for r, u in req:
                    a = av[r]
                    tau = t
                    while tau < end and a[tau] >= u:
                        tau += 1
                    if tau < mt:
                        mt = tau
                if mt >= end:
                    break
                t = mt - d
            if t < s0:
                t = s0
            for r, u in req:
                a = av[r]
                for tau in range(t, t + d):
                    a[tau] -= u
            ns[j] = t
        order2 = sorted(range(n), key=lambda j: (ns[j], j))
        r2 = decode(order2, md)
        return r2, order2

    best = {"c": None, "st": None, "md": None, "o": None, "m": None, "fn": None}

    def consider(r, order, msel):
        if best["c"] is None or r[0] < best["c"]:
            best["c"] = r[0]
            best["st"] = r[1][:]
            best["fn"] = r[2][:]
            best["md"] = r[3][:]
            best["o"] = order[:]
            best["m"] = msel[:]
            return True
        return False

    auto = [-1] * n
    # phase 1: deterministic rules
    for key in keys:
        o = build(key)
        r = decode(o, auto)
        consider(r, o, auto)
        if tl() > BUD * 0.5:
            break
        r2, o2 = fbi(r)
        consider(r2, o2, r2[3])
        if tl() > BUD * 0.5:
            break

    # phase 2: biased random sampling
    rng = random.Random(12345)
    ph2 = BUD * 0.3
    while tl() < ph2:
        key = keys[rng.randrange(len(keys))]
        amp = rng.uniform(0.03, 0.5) * (CP + 1)
        k2 = [key[j] + rng.random() * amp for j in range(n)]
        o = build(k2)
        r = decode(o, auto)
        consider(r, o, auto)
        if r[0] <= best["c"] * 1.08 and tl() < ph2:
            r2, o2 = fbi(r)
            consider(r2, o2, r2[3])

    # phase 3: local search
    multi = [j for j in range(n) if len(jmodes[j]) > 1]
    cur_o = best["o"][:]
    cur_m = best["m"][:]
    cur_c = best["c"]
    cur_fn = best["fn"][:]

    def tardy_of(fn):
        return [j for j in dued if fn[j] > due[j]]

    cur_tardy = tardy_of(cur_fn)
    stall = 0
    stall_lim = max(60, 3 * n)

    def shift(o, i, k):
        j = o.pop(i)
        o.insert(k, j)

    while tl() < BUD:
        o = cur_o[:]
        m = cur_m[:]
        nm = 1 if rng.random() < 0.7 else 2
        for _ in range(nm):
            pos = [0] * n
            for i, x in enumerate(o):
                pos[x] = i
            rr = rng.random()
            if multi and rr < 0.25:
                j = multi[rng.randrange(len(multi))]
                ch = [-1] + list(range(len(jmodes[j])))
                ch = [c for c in ch if c != m[j]]
                m[j] = ch[rng.randrange(len(ch))]
            elif rr < 0.45 and cur_tardy:
                j = cur_tardy[rng.randrange(len(cur_tardy))]
                i = pos[j]
                lo = 0
                for p in preds[j]:
                    if pos[p] + 1 > lo:
                        lo = pos[p] + 1
                if lo < i:
                    k = rng.randint(lo, i - 1)
                    shift(o, i, k)
            else:
                i = rng.randrange(n)
                j = o[i]
                lo = 0
                for p in preds[j]:
                    if pos[p] + 1 > lo:
                        lo = pos[p] + 1
                hi = n - 1
                for s in succs[j]:
                    if pos[s] - 1 < hi:
                        hi = pos[s] - 1
                if hi > lo:
                    if rng.random() < 0.6:
                        w = 1 + rng.randrange(6)
                        k = i + rng.randint(-w, w)
                        if k < lo:
                            k = lo
                        if k > hi:
                            k = hi
                    else:
                        k = rng.randint(lo, hi)
                    if k != i:
                        shift(o, i, k)
        r = decode(o, m)
        c = r[0]
        improved_best = consider(r, o, m)
        if c <= cur_c or rng.random() < 0.01:
            cur_o, cur_m, cur_c, cur_fn = o, m, c, r[2]
            cur_tardy = tardy_of(cur_fn)
            if (improved_best or rng.random() < 0.3) and tl() < BUD:
                r2, o2 = fbi(r)
                if consider(r2, o2, r2[3]):
                    improved_best = True
                if r2[0] < cur_c:
                    cur_o, cur_m, cur_c, cur_fn = o2, r2[3][:], r2[0], r2[2]
                    cur_tardy = tardy_of(cur_fn)
        if improved_best:
            stall = 0
        else:
            stall += 1
        if stall > stall_lim:
            stall = 0
            cur_o = best["o"][:]
            cur_m = best["m"][:]
            cur_c = best["c"]
            cur_fn = best["fn"][:]
            cur_tardy = tardy_of(cur_fn)

    st = best["st"]
    md = best["md"]
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": int(st[j]), "mode": int(jmodes[j][md[j]][3])}
    state["output"] = {"status": "ok", "schedule": sched}
    return state

import time
import random
import heapq


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def solve(state, params):
    t0 = time.process_time()
    budget = 0.72
    inp = state["input"]
    resources = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    for r in rnames:
        cal = resources[r].get("calendar", []) or [[0, 0]]
        cal = sorted([(int(a), int(b)) for a, b in cal])
        cals.append(cal)
        maxcap.append(max(b for a, b in cal))
    n = len(jobs)
    ids = [str(j["id"]) for j in jobs]
    jidx = {}
    for i, x in enumerate(ids):
        jidx[x] = i
    preds = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        ps = set()
        for p in j.get("after", []) or []:
            p = str(p)
            if p not in jidx:
                return _infeasible(state, "job %s references unknown predecessor %s" % (ids[i], p))
            ps.add(jidx[p])
        preds[i] = sorted(ps)
    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
            indeg[i] += 1
    q = [i for i in range(n) if indeg[i] == 0]
    topo = []
    dg = indeg[:]
    while q:
        x = q.pop()
        topo.append(x)
        for s in succs[x]:
            dg[s] -= 1
            if dg[s] == 0:
                q.append(s)
    if len(topo) < n:
        return _infeasible(state, "precedence cycle")
    modes = []
    for i, j in enumerate(jobs):
        ml = []
        for k, m in enumerate(j.get("modes", []) or []):
            req = m.get("requires", {}) or {}
            ok = True
            rl = []
            for rn, u in req.items():
                if rn not in ridx or int(u) > maxcap[ridx[rn]]:
                    ok = False
                    break
                if int(u) > 0:
                    rl.append((ridx[rn], int(u)))
            if ok:
                ml.append((k, int(m["duration"]), rl))
        if not ml:
            return _infeasible(state, "job %s has no feasible mode" % ids[i])
        modes.append(ml)
    rel = [int(j.get("release", 0) or 0) for j in jobs]
    due = [j.get("due") for j in jobs]
    wt = [int(j.get("weight", 0) or 0) if j.get("due") is not None else 0 for j in jobs]
    dueN = [int(d) if d is not None else 0 for d in due]
    maxbp = max([c[-1][0] for c in cals] + [0])
    H = maxbp + max(rel + [0]) + sum(max(m[1] for m in ml) for ml in modes) + 20
    capa = []
    for c in cals:
        arr = [0] * H
        for k, (a, b) in enumerate(c):
            e = c[k + 1][0] if k + 1 < len(c) else H
            for t in range(max(a, 0), min(e, H)):
                arr[t] = b
        capa.append(arr)

    def decode(order, mlist):
        av = [a[:] for a in capa]
        st = [0] * n
        fn = [0] * n
        md = [0] * n
        cost = 0
        mk = 0
        for j in order:
            est = rel[j]
            for p in preds[j]:
                if fn[p] > est:
                    est = fn[p]
            ml = modes[j]
            mj = mlist[j]
            cands = range(len(ml)) if mj < 0 else (mj,)
            best = None
            for mi in cands:
                _, d, req = ml[mi]
                s = est
                t = s
                end = s + d
                while t < end:
                    bad = False
                    for ri, u in req:
                        if av[ri][t] < u:
                            bad = True
                            break
                    if bad:
                        s = t + 1
                        end = s + d
                        t = s
                    else:
                        t += 1
                f = s + d
                sc = f + wt[j] * (f - dueN[j] if f > dueN[j] else 0)
                key = (sc, f, d * sum(u for _, u in req))
                if best is None or key < best[0]:
                    best = (key, mi, s, f)
            _, mi, s, f = best
            for ri, u in ml[mi][2]:
                a = av[ri]
                for t in range(s, f):
                    a[t] -= u
            st[j] = s
            fn[j] = f
            md[j] = mi
            if f > mk:
                mk = f
            if wt[j] and f > dueN[j]:
                cost += wt[j] * (f - dueN[j])
        return cost + mk, st, md

    mind = [min(m[1] for m in ml) for ml in modes]
    es = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            e = max(e, es[p] + mind[p])
        es[j] = e
    cp = max(es[j] + mind[j] for j in range(n)) if n else 0
    lf = [cp] * n
    for j in reversed(topo):
        for s in succs[j]:
            lf[j] = min(lf[j], lf[s] - mind[s])
    tail = [0] * n
    for j in reversed(topo):
        tail[j] = mind[j] + max([tail[s] for s in succs[j]] + [0])
    dl = [lf[j] if due[j] is None or wt[j] == 0 else min(lf[j], dueN[j]) for j in range(n)]
    for j in reversed(topo):
        for s in succs[j]:
            dl[j] = min(dl[j], dl[s] - mind[s])

    def listsched(prio):
        dg2 = indeg[:]
        h = [(prio[i], i) for i in range(n) if dg2[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                dg2[s] -= 1
                if dg2[s] == 0:
                    heapq.heappush(h, (prio[s], s))
        return out

    rng = random.Random(12345)
    base = [-1] * n
    best = None
    cands = [
        [lf[j] for j in range(n)],
        [dl[j] for j in range(n)],
        [-tail[j] for j in range(n)],
        [es[j] for j in range(n)],
        [dl[j] - 3 * wt[j] for j in range(n)],
        [(dl[j], lf[j]) for j in range(n)],
    ]
    for pr in cands:
        o = listsched(pr)
        c, st, md = decode(o, base)
        if best is None or c < best[0]:
            best = (c, o, base[:], st, md)
    k = 0
    while k < 10 and time.process_time() - t0 < budget * 0.25:
        pr = [(dl[j] + rng.random() * (cp * 0.3 + 5), j) for j in range(n)]
        o = listsched(pr)
        c, st, md = decode(o, base)
        if c < best[0]:
            best = (c, o, base[:], st, md)
        k += 1

    cur_c, cur_o, cur_m = best[0], best[1][:], best[2][:]
    pos = [0] * n
    temp = max(1.0, cur_c * 0.01)
    it = 0
    since = 0
    while n > 1:
        if (it & 3) == 0 and time.process_time() - t0 > budget:
            break
        it += 1
        o = cur_o[:]
        m = cur_m[:]
        r = rng.random()
        if r < 0.15:
            j = rng.randrange(n)
            nm = len(modes[j])
            if nm == 1:
                continue
            m[j] = rng.randrange(-1, nm)
            if m[j] == cur_m[j]:
                continue
        else:
            for i, x in enumerate(o):
                pos[x] = i
            i = rng.randrange(n)
            x = o[i]
            lo = max([pos[p] for p in preds[x]] + [-1]) + 1
            hi = min([pos[s] for s in succs[x]] + [n]) - 1
            if hi <= lo:
                continue
            if r < 0.85:
                ni = rng.randint(lo, hi)
            else:
                ni = rng.randint(max(lo, i - 3), min(hi, i + 3))
            if ni == i:
                continue
            o.pop(i)
            o.insert(ni, x)
            if r > 0.95 and len(modes[x]) > 1:
                m[x] = rng.randrange(-1, len(modes[x]))
        c, st, md = decode(o, m)
        d = c - cur_c
        if d <= 0 or rng.random() < pow(2.718281828, -d / temp):
            cur_c, cur_o, cur_m = c, o, m
            if c < best[0]:
                best = (c, o, m, st, md)
                since = 0
        since += 1
        temp = max(0.3, temp * 0.995)
        if since > 300:
            cur_c, cur_o, cur_m = best[0], best[1][:], best[2][:]
            since = 0
            temp = max(1.0, cur_c * 0.005)

    c, o, m, st, md = best
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": st[j], "mode": modes[j][md[j]][0]}
    state["output"] = {"status": "ok", "schedule": sched}
    state["meta"] = {"cost": c, "iters": it}
    return state

import time, random, math, heapq

def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state

def solve(state, params):
    T0 = time.process_time()
    BUDGET = 0.78
    inp = state.get("input") or {}
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    for r in rnames:
        cal = (res[r] or {}).get("calendar") or [[0, 0]]
        cal = sorted([(int(a), int(b)) for a, b in cal])
        cals.append(cal)
        maxcap.append(cal[-1][1])
    n = len(jobs)
    ids = [str(j["id"]) for j in jobs]
    jidx = {}
    for i, s in enumerate(ids):
        jidx[s] = i
    preds = []
    for j in jobs:
        pl = []
        for p in (j.get("after") or []):
            p = str(p)
            if p not in jidx:
                return _infeasible(state, "unknown predecessor " + p)
            q = jidx[p]
            if q not in pl:
                pl.append(q)
        preds.append(pl)
    modes = []
    for j in jobs:
        ml = []
        for mi, m in enumerate(j.get("modes") or []):
            d = int(m.get("duration", 1))
            ok = True
            rq = []
            for r, u in (m.get("requires") or {}).items():
                u = int(u)
                if u <= 0:
                    continue
                if r not in ridx or u > maxcap[ridx[r]]:
                    ok = False
                    break
                rq.append((ridx[r], u))
            if ok:
                ml.append((mi, d, tuple(rq)))
        if not ml:
            return _infeasible(state, "job " + str(j["id"]) + " has no feasible mode")
        modes.append(ml)
    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for j in range(n):
        for p in preds[j]:
            succs[p].append(j)
            indeg[j] += 1
    topo = []
    dq = [j for j in range(n) if indeg[j] == 0]
    deg = indeg[:]
    while dq:
        x = dq.pop()
        topo.append(x)
        for s in succs[x]:
            deg[s] -= 1
            if deg[s] == 0:
                dq.append(s)
    if len(topo) < n:
        return _infeasible(state, "precedence cycle")
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    due = [j.get("due") for j in jobs]
    wt = [int(j.get("weight", 0) or 0) for j in jobs]
    hasdue = [due[j] is not None and wt[j] > 0 for j in range(n)]
    dueI = [int(due[j]) if due[j] is not None else 0 for j in range(n)]
    maxbp = max([c[-1][0] for c in cals] + [0])
    H = maxbp + max(rel + [0]) + sum(max(m[1] for m in ml) for ml in modes) + 5
    base = []
    for c in cals:
        a = [0] * H
        for k, (t, cp) in enumerate(c):
            e = c[k + 1][0] if k + 1 < len(c) else H
            e = min(e, H)
            for x in range(max(t, 0), e):
                a[x] = cp
        base.append(a)
    mind = [min(m[1] for m in ml) for ml in modes]

    def decode(order, msel, alpha, rnd):
        avail = [a[:] for a in base]
        fin = [0] * n
        st = [0] * n
        ch = [0] * n
        for j in order:
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            if msel is not None:
                cands = (modes[j][msel[j]],)
                cidx = (msel[j],)
            else:
                cands = modes[j]
                cidx = range(len(cands))
            best = None
            for k, (mi, d, rq) in zip(cidx, cands):
                t = est
                if rq:
                    while True:
                        ok = True
                        for ri, u in rq:
                            a = avail[ri]
                            for x in range(t + d - 1, t - 1, -1):
                                if a[x] < u:
                                    t = x + 1
                                    ok = False
                                    break
                            if not ok:
                                break
                        if ok:
                            break
                f = t + d
                if len(cands) > 1:
                    sc = f
                    if hasdue[j] and f > dueI[j]:
                        sc += wt[j] * (f - dueI[j])
                    if alpha:
                        load = 0.0
                        for ri, u in rq:
                            load += u * d / maxcap[ri]
                        sc += alpha * load
                    if rnd:
                        sc += rnd * random.random()
                else:
                    sc = 0
                if best is None or sc < best[0]:
                    best = (sc, k, t, d, rq)
            _, k, t, d, rq = best
            for ri, u in rq:
                a = avail[ri]
                for x in range(t, t + d):
                    a[x] -= u
            st[j] = t
            fin[j] = t + d
            ch[j] = k
        cost = max(fin) if n else 0
        for j in range(n):
            if hasdue[j] and fin[j] > dueI[j]:
                cost += wt[j] * (fin[j] - dueI[j])
        return cost, st, ch

    es = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            e = max(e, es[p] + mind[p])
        es[j] = e
    cpl = max(es[j] + mind[j] for j in range(n)) if n else 0
    lf = [cpl] * n
    lfd = [cpl] * n
    for j in reversed(topo):
        v = cpl
        vd = cpl
        if hasdue[j]:
            vd = min(vd, dueI[j])
        for s in succs[j]:
            v = min(v, lf[s] - mind[s])
            vd = min(vd, lfd[s] - mind[s])
        lf[j] = v
        lfd[j] = vd
    nsucc = [0] * n
    for j in reversed(topo):
        nsucc[j] = len(succs[j]) + sum(nsucc[s] for s in succs[j]) * 0.5
    rules = [
        [lf[j] - mind[j] for j in range(n)],
        [lfd[j] - mind[j] for j in range(n)],
        [lf[j] for j in range(n)],
        [es[j] for j in range(n)],
        [-nsucc[j] for j in range(n)],
        [(lfd[j] - mind[j]) - 2.0 * wt[j] for j in range(n)],
    ]

    def mkorder(pr, noise):
        dg = indeg[:]
        h = []
        for j in range(n):
            if dg[j] == 0:
                heapq.heappush(h, (pr[j] + noise * random.random(), j))
        out = []
        while h:
            _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                dg[s] -= 1
                if dg[s] == 0:
                    heapq.heappush(h, (pr[s] + noise * random.random(), s))
        return out

    def norm(order, st):
        pos = {j: i for i, j in enumerate(order)}
        return sorted(order, key=lambda j: (st[j], pos[j]))

    best = None
    it = 0
    spread = max(1.0, cpl * 0.15)
    p1 = BUDGET * 0.3
    while True:
        el = time.process_time() - T0
        if it > len(rules) * 3 and el > p1:
            break
        if el > BUDGET:
            break
        r = rules[it % len(rules)]
        noise = 0.0 if it < len(rules) else spread * random.random()
        alpha = 0.0 if it < len(rules) else random.random() * 3.0
        if len(rules) <= it < 2 * len(rules):
            alpha = 1.0
        order = mkorder(r, noise)
        c, st, ch = decode(order, None, alpha,
                           0.5 if it >= 3 * len(rules) and random.random() < 0.3 else 0.0)
        if best is None or c < best[0]:
            best = (c, norm(order, st), ch, st)
        it += 1

    cur = (best[0], best[1][:], best[2][:])
    multi = [j for j in range(n) if len(modes[j]) > 1]
    T = max(0.5, best[0] * 0.01)
    lastimp = 0
    k = 0
    while n > 0:
        k += 1
        if (k & 7) == 0:
            el = time.process_time() - T0
            if el > BUDGET:
                break
            frac = (el - p1) / max(1e-6, BUDGET - p1)
            T = max(0.05, best[0] * 0.01 * (1 - frac))
        order = cur[1][:]
        ms = cur[2][:]
        nm = 1 if random.random() < 0.7 else random.randint(2, 4)
        for _ in range(nm):
            mv = random.random()
            if multi and mv < 0.3:
                j = random.choice(multi)
                ms[j] = random.randrange(len(modes[j]))
            else:
                i = random.randrange(n)
                j = order.pop(i)
                pos = {x: q for q, x in enumerate(order)}
                lo = 0
                for p in preds[j]:
                    if pos[p] + 1 > lo:
                        lo = pos[p] + 1
                hi = len(order)
                for s in succs[j]:
                    if pos[s] < hi:
                        hi = pos[s]
                if mv < 0.65:
                    a0 = max(lo, i - 3)
                    b0 = min(hi, i + 3)
                    ni = random.randint(a0, b0) if a0 <= b0 else i
                else:
                    ni = random.randint(lo, hi)
                order.insert(ni, j)
        c, st, ch = decode(order, ms, 0, 0)
        if c <= cur[0] or random.random() < math.exp(-(c - cur[0]) / T):
            cur = (c, norm(order, st), ms)
            if c < best[0]:
                best = (c, cur[1][:], ms[:], st)
                lastimp = k
        if k - lastimp > 400 + 4 * n:
            cur = (best[0], best[1][:], best[2][:])
            lastimp = k
    c, st, ch = best[0], best[3], best[2]
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": int(st[j]), "mode": int(modes[j][ch[j]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    state["cost"] = c
    return state

import time, heapq, random

def solve(state, params):
    t0 = time.process_time()
    inp = state["input"]
    res = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    lastbp = 0
    for r in rnames:
        raw = res[r].get("calendar", [[0, 0]]) or [[0, 0]]
        cal = sorted([[int(a), int(c)] for a, c in raw], key=lambda x: x[0])
        cals.append(cal)
        maxcap.append(cal[-1][1])
        lastbp = max(lastbp, cal[-1][0])
    n = len(jobs)
    ids = [str(j["id"]) for j in jobs]
    jidx = {}
    for i, s in enumerate(ids):
        jidx[s] = i
    preds = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        seen = set()
        for p in j.get("after", []) or []:
            p = str(p)
            if p not in jidx:
                state["output"] = {"status": "infeasible", "reason": "unknown predecessor %s of job %s" % (p, ids[i])}
                return state
            k = jidx[p]
            if k not in seen:
                seen.add(k)
                preds[i].append(k)
    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
            indeg[i] += 1
    topo = []
    dq = [i for i in range(n) if indeg[i] == 0]
    deg = indeg[:]
    while dq:
        x = dq.pop()
        topo.append(x)
        for s in succs[x]:
            deg[s] -= 1
            if deg[s] == 0:
                dq.append(s)
    if len(topo) < n:
        state["output"] = {"status": "infeasible", "reason": "precedence cycle"}
        return state
    modes = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes", []) or []):
            req = m.get("requires", {}) or {}
            ok = True
            rq = []
            for r, q in req.items():
                q = int(q)
                if r not in ridx or q > maxcap[ridx[r]]:
                    ok = False
                    break
                if q > 0:
                    rq.append((ridx[r], q))
            if ok:
                ml.append((mi, int(m["duration"]), rq))
        if not ml:
            state["output"] = {"status": "infeasible", "reason": "job %s has no feasible mode" % ids[i]}
            return state
        modes.append(ml)
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    rel = [int(j.get("release", 0) or 0) for j in jobs]
    due = [j.get("due") for j in jobs]
    wt = [int(j.get("weight", 0) or 0) for j in jobs]
    hasdue = [d is not None for d in due]
    duev = [int(d) if d is not None else 0 for d in due]
    H = max(lastbp, max(rel)) + sum(max(m[1] for m in ml) for ml in modes) + 5
    R = len(rnames)
    base = []
    for r in range(R):
        arr = [0] * H
        cal = cals[r]
        for k in range(len(cal)):
            a, c = cal[k]
            b = cal[k + 1][0] if k + 1 < len(cal) else H
            a = max(0, a)
            b = min(b, H)
            for t in range(a, b):
                arr[t] = c
        base.append(arr)
    rw = [1.0 / max(1, maxcap[r]) for r in range(R)]
    mload = []
    for i in range(n):
        mload.append([d * sum(q * rw[r] for r, q in rq) for (_, d, rq) in modes[i]])
    nm = [len(modes[i]) for i in range(n)]

    def decode(keys, mg):
        av = [a[:] for a in base]
        start = [0] * n
        fin = [0] * n
        cm = [0] * n
        dg = indeg[:]
        heap = [(keys[i], i) for i in range(n) if dg[i] == 0]
        heapq.heapify(heap)
        cost_t = 0
        mk = 0
        while heap:
            _, j = heapq.heappop(heap)
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            g = mg[j]
            cand = range(nm[j]) if g < 0 else (g,)
            best = None
            ml = modes[j]
            for mi in cand:
                _, d, rq = ml[mi]
                t = est
                if rq:
                    lst = [(av[r], q) for r, q in rq]
                    while True:
                        tau = t + d - 1
                        bad = -1
                        while tau >= t:
                            for a, q in lst:
                                if a[tau] < q:
                                    bad = tau
                                    break
                            if bad >= 0:
                                break
                            tau -= 1
                        if bad < 0:
                            break
                        t = bad + 1
                f = t + d
                sc = f
                if hasdue[j] and f > duev[j]:
                    sc += wt[j] * (f - duev[j])
                sc = sc * 1000.0 + mload[j][mi]
                if best is None or sc < best[0]:
                    best = (sc, mi, t, f)
            _, mi, t, f = best
            for r, q in ml[mi][2]:
                a = av[r]
                for tau in range(t, f):
                    a[tau] -= q
            start[j] = t
            fin[j] = f
            cm[j] = mi
            if f > mk:
                mk = f
            if hasdue[j] and f > duev[j]:
                cost_t += wt[j] * (f - duev[j])
            for s in succs[j]:
                dg[s] -= 1
                if dg[s] == 0:
                    heapq.heappush(heap, (keys[s], s))
        return mk + cost_t, start, cm

    mind = [min(m[1] for m in modes[i]) for i in range(n)]
    es = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            e = max(e, es[p] + mind[p])
        es[j] = e
    cp = max(es[j] + mind[j] for j in range(n))
    ls = [0] * n
    lsd = [0] * n
    BIG = cp * 10 + 10 ** 6
    for j in reversed(topo):
        l = cp - mind[j]
        ld = (duev[j] - mind[j]) if hasdue[j] else BIG
        for s in succs[j]:
            l = min(l, ls[s] - mind[j])
            ld = min(ld, lsd[s] - mind[j])
        ls[j] = l
        lsd[j] = ld
    nsc = [len(succs[j]) for j in range(n)]
    wl = [wt[j] if hasdue[j] else 0 for j in range(n)]
    rules = []
    rules.append([float(ls[j]) for j in range(n)])
    rules.append([float(min(ls[j], lsd[j])) for j in range(n)])
    rules.append([float(min(ls[j], lsd[j]) - 0.5 * min(wl[j], 20)) for j in range(n)])
    rules.append([float(es[j]) + 0.01 * ls[j] for j in range(n)])
    rules.append([float(ls[j] - es[j]) for j in range(n)])
    rules.append([float(ls[j] - 2 * nsc[j]) for j in range(n)])
    rules.append([float(lsd[j] if lsd[j] < BIG else ls[j] + cp) for j in range(n)])
    rng = random.Random(12345)
    TL = 0.75
    best = None
    greedy = [-1] * n
    for rk in rules:
        c, s, m = decode(rk, greedy)
        if best is None or c < best[0]:
            best = (c, rk[:], greedy[:], s, m)
    minload_modes = []
    for j in range(n):
        if nm[j] > 1:
            bk = 0
            for k in range(1, nm[j]):
                if (mload[j][k], modes[j][k][1]) < (mload[j][bk], modes[j][bk][1]):
                    bk = k
            minload_modes.append(bk)
        else:
            minload_modes.append(-1)
    for rk in rules[:3]:
        mg = minload_modes[:]
        c, s, m = decode(rk, mg)
        if c < best[0]:
            best = (c, rk[:], mg, s, m)
    it = 0
    scale = max(1.0, cp * 0.15)
    while time.process_time() - t0 < TL * 0.3:
        rk = rules[rng.randrange(len(rules))]
        sc = scale * rng.random()
        keys = [rk[j] + rng.gauss(0, sc) for j in range(n)]
        mg = greedy[:]
        if rng.random() < 0.3:
            for j in range(n):
                if nm[j] > 1 and rng.random() < 0.2:
                    mg[j] = rng.randrange(nm[j])
        c, s, m = decode(keys, mg)
        it += 1
        if c < best[0]:
            best = (c, keys, mg, s, m)
    cur = best
    stag = 0
    while time.process_time() - t0 < TL:
        keys = cur[1][:]
        mg = cur[2][:]
        nmv = 1 + (rng.random() < 0.5) + (rng.random() < 0.25)
        for _ in range(nmv):
            r = rng.random()
            j = rng.randrange(n)
            if r < 0.5:
                k = rng.randrange(n)
                keys[j] = keys[k] + (rng.random() - 0.5) * 0.01
            elif r < 0.7:
                k = rng.randrange(n)
                keys[j], keys[k] = keys[k], keys[j]
            elif r < 0.85:
                if nm[j] > 1:
                    mg[j] = rng.randrange(-1, nm[j])
                else:
                    keys[j] -= rng.random() * scale
            else:
                st = cur[3]
                keys = [float(st[i]) + 0.001 * keys[i] for i in range(n)]
                keys[j] = st[j] - rng.random() * scale
        c, s, m = decode(keys, mg)
        it += 1
        if c <= cur[0]:
            if c < cur[0]:
                stag = 0
            else:
                stag += 1
            cur = (c, keys, mg, s, m)
            if c < best[0]:
                best = cur
        else:
            stag += 1
        if stag > 300:
            stag = 0
            cur = best
    _, _, _, s, m = best
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": int(s[j]), "mode": int(modes[j][m[j]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    return state

import time, heapq, random

def solve(state, params):
    t0 = time.process_time()
    inp = state["input"]
    res = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    rnames = list(res.keys())
    rix = {r: i for i, r in enumerate(rnames)}
    R = len(rnames)
    cals = []
    maxcap = []
    tlast = 0
    for r in rnames:
        cal = sorted([(int(a), int(b)) for a, b in res[r].get("calendar", [[0, 0]])])
        if not cal:
            cal = [(0, 0)]
        cals.append(cal)
        maxcap.append(cal[-1][1])
        tlast = max(tlast, cal[-1][0])
    n = len(jobs)
    ids = [str(j["id"]) for j in jobs]
    jix = {}
    for i, s in enumerate(ids):
        jix[s] = i
    if len(jix) != n:
        state["output"] = {"status": "infeasible", "reason": "duplicate job id"}
        return state
    preds = [[] for _ in range(n)]
    succs = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        for p in j.get("after", []) or []:
            p = str(p)
            if p not in jix:
                state["output"] = {"status": "infeasible", "reason": "unknown predecessor " + p}
                return state
            pi = jix[p]
            if pi not in preds[i]:
                preds[i].append(pi)
                succs[pi].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    topo = [i for i in range(n) if indeg[i] == 0]
    k = 0
    while k < len(topo):
        u = topo[k]; k += 1
        for v in succs[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                topo.append(v)
    if len(topo) < n:
        state["output"] = {"status": "infeasible", "reason": "precedence cycle"}
        return state
    modes = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes", []) or []):
            d = int(m.get("duration", 1))
            ok = True
            rq = []
            for r, u in (m.get("requires", {}) or {}).items():
                u = int(u)
                if r not in rix:
                    if u <= 0:
                        continue
                    ok = False; break
                if u > maxcap[rix[r]]:
                    ok = False; break
                if u > 0:
                    rq.append((rix[r], u))
            if ok:
                ml.append((mi, d, rq))
        if not ml:
            state["output"] = {"status": "infeasible", "reason": "job " + ids[i] + " has no feasible mode"}
            return state
        modes.append(ml)
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    due = [j.get("due") for j in jobs]
    wt = [int(j.get("weight", 0) or 0) for j in jobs]
    mindur = [min(m[1] for m in ml) for ml in modes]
    maxdur = [max(m[1] for m in ml) for ml in modes]
    H = max(tlast, max(rel) if rel else 0) + sum(maxdur) + 5
    base = []
    for ri in range(R):
        cal = cals[ri]
        arr = [0] * H
        for k2 in range(len(cal)):
            a = cal[k2][0]
            b = cal[k2 + 1][0] if k2 + 1 < len(cal) else H
            if a >= H:
                break
            b = min(b, H)
            c = cal[k2][1]
            for x in range(a, b):
                arr[x] = c
        base.append(arr)
    duelist = [(i, int(due[i])) for i in range(n) if due[i] is not None]

    def decode(keys, mg):
        free = [a[:] for a in base]
        fin = [0] * n
        st = [0] * n
        md = [0] * n
        ind = [len(preds[i]) for i in range(n)]
        est = rel[:]
        h = [(keys[i], i) for i in range(n) if ind[i] == 0]
        heapq.heapify(h)
        order = []
        while h:
            _, j = heapq.heappop(h)
            order.append(j)
            e = est[j]
            g = mg[j]
            cands = modes[j] if g < 0 else (modes[j][g],)
            best = None
            for mk, m in enumerate(cands):
                d = m[1]; rq = m[2]
                t = e
                if rq:
                    while True:
                        end = t + d
                        nt = t
                        for (ri, u) in rq:
                            fr = free[ri]
                            for x in range(end - 1, nt - 1, -1):
                                if fr[x] < u:
                                    nt = x + 1
                                    break
                        if nt == t:
                            break
                        t = nt
                f = t + d
                if best is None or f < best[0]:
                    best = (f, t, m, mk)
            f, t, m, mk = best
            for (ri, u) in m[2]:
                fr = free[ri]
                for x in range(t, f):
                    fr[x] -= u
            st[j] = t; fin[j] = f
            md[j] = mk if g < 0 else g
            for s in succs[j]:
                if f > est[s]:
                    est[s] = f
                ind[s] -= 1
                if ind[s] == 0:
                    heapq.heappush(h, (keys[s], s))
        cost = max(fin) if n else 0
        for i, dd in duelist:
            if fin[i] > dd:
                cost += wt[i] * (fin[i] - dd)
        return cost, st, md, fin, order

    INF = 10 ** 9
    UB = H
    LF = [UB] * n
    for j in reversed(topo):
        for s in succs[j]:
            v = LF[s] - mindur[s]
            if v < LF[j]:
                LF[j] = v
    DL = [INF] * n
    for j in reversed(topo):
        v = int(due[j]) if due[j] is not None else INF
        for s in succs[j]:
            if DL[s] < INF:
                v = min(v, DL[s] - mindur[s])
        DL[j] = v
    nsucc = [0] * n
    reach = [0] * n
    for j in reversed(topo):
        b = 1 << j
        for s in succs[j]:
            b |= reach[s]
        reach[j] = b
        nsucc[j] = bin(b).count("1") - 1
    ES = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            e = max(e, ES[p] + mindur[p])
        ES[j] = e
    rules = []
    rules.append([float(LF[i] - mindur[i]) for i in range(n)])
    rules.append([float(LF[i]) for i in range(n)])
    rules.append([float(min(LF[i] - mindur[i] - UB, (DL[i] - mindur[i] if DL[i] < INF else LF[i] - UB))) for i in range(n)])
    rules.append([float(ES[i] + 0.01 * (LF[i])) for i in range(n)])
    rules.append([float(-nsucc[i]) for i in range(n)])
    rules.append([float(min(LF[i] - mindur[i] - UB, DL[i] - mindur[i] if DL[i] < INF else INF) - 3 * wt[i]) for i in range(n)])
    rules.append([float(i) for i in range(n)])
    rng = random.Random(12345)
    LIMIT = 0.78
    best = None

    def consider(keys, mg):
        nonlocal best
        c, st, md, fin, order = decode(keys, mg)
        if best is None or c < best[0]:
            best = (c, st[:], md[:], keys[:], mg[:], order)
        return c, order, fin

    greedy = [-1] * n
    mindm = [min(range(len(modes[i])), key=lambda k3, i=i: (modes[i][k3][1], sum(u for _, u in modes[i][k3][2]))) for i in range(n)]
    minrm = [min(range(len(modes[i])), key=lambda k3, i=i: (sum(u * modes[i][k3][1] for _, u in modes[i][k3][2]), modes[i][k3][1])) for i in range(n)]
    first = True
    for rk in rules:
        for mg in (greedy, mindm, minrm):
            if not first and time.process_time() - t0 > LIMIT * 0.4:
                break
            first = False
            consider(rk, mg)
    sc = max(1.0, (max(LF) - min(LF)) * 0.1) if n else 1.0
    while time.process_time() - t0 < LIMIT * 0.3:
        rk = rules[rng.randrange(len(rules))]
        rk2 = [rk[i] + rng.random() * sc * rng.random() for i in range(n)]
        mg = best[4] if rng.random() < 0.5 else greedy
        consider(rk2, mg)
    order = best[5]
    cur_keys = [0.0] * n
    for p, j in enumerate(order):
        cur_keys[j] = float(p)
    cur_mg = best[4][:]
    c, st, md, fin, order = decode(cur_keys, cur_mg)
    if c < best[0]:
        best = (c, st[:], md[:], cur_keys[:], cur_mg[:], order)
    cur_c = c; cur_fin = fin
    stall = 0
    while time.process_time() - t0 < LIMIT and n > 1:
        keys = cur_keys[:]
        mg = cur_mg[:]
        nm = 1 if rng.random() < 0.7 else rng.randint(2, 4)
        for _ in range(nm):
            r = rng.random()
            if r < 0.35:
                mk = max(cur_fin)
                cand = [i for i in range(n) if cur_fin[i] == mk]
                for i, dd in duelist:
                    if cur_fin[i] > dd and wt[i] > 0:
                        cand.append(i)
                        if wt[i] > 1:
                            cand.append(i)
                j = rng.choice(cand)
                while preds[j] and rng.random() < 0.3:
                    j = rng.choice(preds[j])
                tgt = keys[j] - rng.randint(1, max(1, min(n, 20)))
                keys[j] = tgt - 0.5
            elif r < 0.65:
                j = rng.randrange(n)
                keys[j] = keys[j] + rng.choice((-1, 1)) * (rng.randint(1, max(1, n // 5)) + 0.5)
            elif r < 0.8:
                a = rng.randrange(n); b = rng.randrange(n)
                keys[a], keys[b] = keys[b], keys[a]
            else:
                j = rng.randrange(n)
                if len(modes[j]) > 1:
                    mg[j] = rng.randrange(-1, len(modes[j]))
        c, st, md, fin, order = decode(keys, mg)
        if c < best[0]:
            best = (c, st[:], md[:], keys[:], mg[:], order)
        if c <= cur_c:
            if c < cur_c:
                stall = 0
            else:
                stall += 1
            cur_c = c; cur_fin = fin; cur_mg = mg
            cur_keys = [0.0] * n
            for p, jj in enumerate(order):
                cur_keys[jj] = float(p)
        else:
            stall += 1
        if stall > 150:
            stall = 0
            cur_keys = [0.0] * n
            for p, jj in enumerate(best[5]):
                cur_keys[jj] = float(p) + rng.random() * 3
            cur_mg = best[4][:]
            c, st, md, fin, order = decode(cur_keys, cur_mg)
            if c < best[0]:
                best = (c, st[:], md[:], cur_keys[:], cur_mg[:], order)
            cur_c = c; cur_fin = fin
    c, st, md, _, _, _ = best
    sched = {}
    for i in range(n):
        sched[ids[i]] = {"start": int(st[i]), "mode": int(modes[i][md[i]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    state["cost"] = c
    return state

import time, random, heapq


def solve(state, params):
    T0 = time.process_time()
    BUDGET = 0.68
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    lastbp = 0
    for r in rnames:
        c = (resources[r] or {}).get("calendar") or [[0, 0]]
        c = sorted([(int(a[0]), int(a[1])) for a in c])
        cals.append(c)
        maxcap.append(c[-1][1])
        lastbp = max(lastbp, c[-1][0])
    n = len(jobs)
    ids = [str(j.get("id")) for j in jobs]
    pos = {}
    for i, s in enumerate(ids):
        pos[s] = i
    preds = [[] for _ in range(n)]
    succs = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        seen = set()
        for p in (j.get("after") or []):
            p = str(p)
            if p not in pos:
                state["output"] = {"status": "infeasible",
                                   "reason": "job %s references unknown predecessor %s" % (ids[i], p)}
                return state
            k = pos[p]
            if k in seen:
                continue
            seen.add(k)
            preds[i].append(k)
            succs[k].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]
    topo = []
    while q:
        x = q.pop()
        topo.append(x)
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    if len(topo) < n:
        state["output"] = {"status": "infeasible", "reason": "precedence relation has a cycle"}
        return state
    modes = []
    rel = []
    due = []
    wt = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes") or []):
            d = max(1, int(m.get("duration", 1)))
            req = []
            ok = True
            for rn, u in (m.get("requires") or {}).items():
                u = int(u)
                if rn not in ridx:
                    ok = False
                    break
                if u <= 0:
                    continue
                if u > maxcap[ridx[rn]]:
                    ok = False
                    break
                req.append((ridx[rn], u))
            if ok:
                ml.append((mi, d, req))
        if not ml:
            state["output"] = {"status": "infeasible",
                               "reason": "job %s has no mode fitting the resources" % ids[i]}
            return state
        modes.append(ml)
        rel.append(max(0, int(j.get("release") or 0)))
        dd = j.get("due")
        due.append(None if dd is None else int(dd))
        wt.append(max(0, int(j.get("weight") or 0)))
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state

    nr = len(rnames)
    maxd = [max(m[1] for m in modes[i]) for i in range(n)]
    mind = [min(m[1] for m in modes[i]) for i in range(n)]
    H = max(lastbp, max(rel)) + sum(maxd) + max(maxd) + 5
    base = []
    for r in range(nr):
        arr = [0] * H
        c = cals[r]
        for k in range(len(c)):
            a = c[k][0]
            b = c[k + 1][0] if k + 1 < len(c) else H
            a = min(max(a, 0), H)
            b = min(max(b, 0), H)
            for t in range(a, b):
                arr[t] = c[k][1]
        base.append(arr)
    duejobs = [i for i in range(n) if due[i] is not None and wt[i] > 0]

    def cost_of(fin):
        c = max(fin)
        for i in duejobs:
            x = fin[i] - due[i]
            if x > 0:
                c += wt[i] * x
        return c

    def earliest(av, req, t, d):
        if d <= 0 or not req:
            return t
        while True:
            ok = True
            for (r, u) in req:
                a = av[r]
                k = t + d - 1
                while k >= t:
                    if a[k] < u:
                        break
                    k -= 1
                if k >= t:
                    t = k + 1
                    ok = False
                    break
            if ok:
                return t

    def decode(order, mv):
        av = [a[:] for a in base]
        st = [0] * n
        fin = [0] * n
        for j in order:
            m = modes[j][mv[j]]
            d = m[1]
            req = m[2]
            t = rel[j]
            for p in preds[j]:
                if fin[p] > t:
                    t = fin[p]
            t = earliest(av, req, t, d)
            st[j] = t
            fin[j] = t + d
            for (r, u) in req:
                a = av[r]
                for k in range(t, t + d):
                    a[k] -= u
        return st, fin

    def decode_greedy(order, rng, noise):
        av = [a[:] for a in base]
        st = [0] * n
        fin = [0] * n
        mv = [0] * n
        cur_ms = 0
        for j in order:
            t0 = rel[j]
            for p in preds[j]:
                if fin[p] > t0:
                    t0 = fin[p]
            bb = None
            ml = modes[j]
            for mi in range(len(ml)):
                m = ml[mi]
                d = m[1]
                t = earliest(av, m[2], t0, d)
                f = t + d
                sc = f
                if due[j] is not None and f > due[j]:
                    sc += wt[j] * (f - due[j])
                if f > cur_ms:
                    sc += (f - cur_ms)
                use = 0.0
                for (r, u) in m[2]:
                    use += u * d / (maxcap[r] + 1.0)
                sc += 0.05 * use
                if noise > 0:
                    sc += rng.random() * noise
                if bb is None or sc < bb[0]:
                    bb = (sc, mi, t, d)
            _, mi, t, d = bb
            mv[j] = mi
            st[j] = t
            fin[j] = t + d
            if t + d > cur_ms:
                cur_ms = t + d
            for (r, u) in ml[mi][2]:
                a = av[r]
                for k in range(t, t + d):
                    a[k] -= u
        return st, fin, mv

    es = [0] * n
    for j in topo:
        t = rel[j]
        for p in preds[j]:
            if es[p] + mind[p] > t:
                t = es[p] + mind[p]
        es[j] = t
    cp = max(es[j] + mind[j] for j in range(n))
    INF = 10 ** 9
    lf = [cp] * n
    lfd = [INF] * n
    for j in reversed(topo):
        x = cp
        y = INF if due[j] is None or wt[j] == 0 else due[j]
        for s in succs[j]:
            if lf[s] - mind[s] < x:
                x = lf[s] - mind[s]
            if lfd[s] - mind[s] < y:
                y = lfd[s] - mind[s]
        lf[j] = x
        lfd[j] = y
    lst = [lf[j] - mind[j] for j in range(n)]
    lsd = [lfd[j] - mind[j] for j in range(n)]
    nsucc_tot = [0.0] * n
    for j in reversed(topo):
        nsucc_tot[j] = len(succs[j]) + sum(nsucc_tot[s] for s in succs[j]) * 0.5
    topo_pos = [0] * n
    for k, j in enumerate(topo):
        topo_pos[j] = k

    def make_order(key):
        indeg2 = [len(preds[i]) for i in range(n)]
        h = [(key[i], i) for i in range(n) if indeg2[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                indeg2[s] -= 1
                if indeg2[s] == 0:
                    heapq.heappush(h, (key[s], s))
        return out

    rng = random.Random(12345)
    best = None

    def consider(c, order, mv, st):
        nonlocal best
        if best is None or c < best[0]:
            best = (c, list(order), list(mv), list(st))

    def key_variant(v, noise):
        key = [0.0] * n
        for i in range(n):
            a = lst[i]
            b = lsd[i]
            if v == 0:
                k = min(a, b)
            elif v == 1:
                k = a
            elif v == 2:
                k = min(a, b) - 0.3 * nsucc_tot[i]
            else:
                k = es[i] + 0.5 * min(a, b)
            if v != 1:
                k = max(k, rel[i])
            key[i] = k + (rng.random() * noise if noise > 0 else 0) + rng.random() * 1e-3
        return key

    def fbi(order, mv, st):
        fin = [st[j] + modes[j][mv[j]][1] for j in range(n)]
        C = max(fin)
        ordb = sorted(range(n), key=lambda j: -fin[j])
        av = [a[:] for a in base]
        bst = [0] * n
        for j in ordb:
            m = modes[j][mv[j]]
            d = m[1]
            req = m[2]
            lim = C
            for s in succs[j]:
                if bst[s] < lim:
                    lim = bst[s]
            t = lim - d
            found = False
            while t >= rel[j]:
                bad = -1
                for (r, u) in req:
                    a = av[r]
                    for k in range(t, t + d):
                        if a[k] < u:
                            bad = k
                            break
                    if bad >= 0:
                        break
                if bad < 0:
                    found = True
                    break
                t = bad - d
            if not found:
                return None
            bst[j] = t
            for (r, u) in req:
                a = av[r]
                for k in range(t, t + d):
                    a[k] -= u
        neworder = sorted(range(n), key=lambda j: (bst[j], topo_pos[j]))
        st2, fin2 = decode(neworder, mv)
        return cost_of(fin2), neworder, st2

    def improve_fbi(c, order, mv, st, rounds=3):
        for _ in range(rounds):
            r = fbi(order, mv, st)
            if r is None or r[0] >= c:
                if r is not None and r[0] == c:
                    order, st = r[1], r[2]
                break
            c, order, st = r
        return c, order, st

    # Phase 1: deterministic priority rules
    for v in range(4):
        order = make_order(key_variant(v, 0))
        st, fin, mv = decode_greedy(order, rng, 0)
        consider(cost_of(fin), order, mv, st)
        mv2 = [min(range(len(modes[i])), key=lambda m: modes[i][m][1]) for i in range(n)]
        st, fin = decode(order, mv2)
        consider(cost_of(fin), order, mv2, st)

    c, o, mv, st = best
    c2, o2, st2 = improve_fbi(c, o, mv, st)
    consider(c2, o2, mv, st2)

    # Phase 2: randomized biased sampling + FBI
    p1_end = 0.35 * BUDGET
    it = 0
    spread = max(1.0, cp * 0.15)
    while time.process_time() - T0 < p1_end:
        it += 1
        v = it % 4
        order = make_order(key_variant(v, spread * rng.random()))
        st, fin, mv = decode_greedy(order, rng, rng.random() * 3.0)
        c = cost_of(fin)
        if c < best[0] * 1.05:
            c, order, st = improve_fbi(c, order, mv, st, 2)
        consider(c, order, mv, st)

    # Phase 3: late-acceptance local search over (list, modes)
    c, order, mv, st = best
    order = sorted(range(n), key=lambda j: (st[j], topo_pos[j]))
    cur = (c, order, list(mv))
    LA = 30
    hist = [c] * LA
    multi = [i for i in range(n) if len(modes[i]) > 1]
    step = 0
    while True:
        if (step & 7) == 0 and time.process_time() - T0 > BUDGET:
            break
        step += 1
        cc, order, mvc = cur
        mv2 = mvc
        o2 = order
        typ = rng.random()
        if multi and typ < 0.3:
            mv2 = list(mvc)
            j = rng.choice(multi)
            mv2[j] = rng.randrange(len(modes[j]))
            if mv2[j] == mvc[j]:
                mv2[j] = (mv2[j] + 1) % len(modes[j])
            if rng.random() < 0.3:
                j = rng.choice(multi)
                mv2[j] = rng.randrange(len(modes[j]))
        if typ >= 0.3 or rng.random() < 0.3:
            o2 = list(order)
            p = rng.randrange(n)
            j = o2[p]
            del o2[p]
            lo = 0
            hi = len(o2)
            ps = set(preds[j])
            ss = set(succs[j])
            for k in range(len(o2)):
                x = o2[k]
                if x in ps:
                    lo = k + 1
                elif x in ss:
                    hi = k
                    break
            if hi < lo:
                hi = lo
            if rng.random() < 0.7:
                qq = p + rng.randint(-8, 8)
                qq = min(max(qq, lo), hi)
            else:
                qq = rng.randint(lo, hi)
            o2.insert(qq, j)
        st2, fin2 = decode(o2, mv2)
        c2 = cost_of(fin2)
        hv = hist[step % LA]
        if c2 <= cc or c2 <= hv:
            o2 = sorted(range(n), key=lambda jj: (st2[jj], topo_pos[jj]))
            cur = (c2, o2, mv2)
            consider(c2, o2, mv2, st2)
            if c2 < best[0] + 1 and (step % 5 == 0):
                c3, o3, st3 = improve_fbi(c2, o2, mv2, st2, 2)
                if c3 < c2:
                    cur = (c3, o3, mv2)
                    consider(c3, o3, mv2, st3)
        hist[step % LA] = cur[0]
        if step % 2000 == 0:
            cur = (best[0], list(best[1]), list(best[2]))

    c, order, mv, st = best
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": int(st[j]), "mode": int(modes[j][mv[j]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    return state

import time
import random
import heapq


def solve(state, params):
    t_start = time.process_time()
    budget = 0.75
    inp = state.get("input", {}) or {}
    resources = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state

    # --- resources ---
    rnames = list(resources.keys())
    rindex = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    maxbreak = 0
    for r in rnames:
        cal = resources[r].get("calendar", [[0, 0]]) or [[0, 0]]
        cal = [(int(a), int(b)) for a, b in cal]
        cals.append(cal)
        maxcap.append(cal[-1][1])
        maxbreak = max(maxbreak, cal[-1][0])

    ids = [str(j.get("id")) for j in jobs]
    idx = {jid: i for i, jid in enumerate(ids)}

    # --- feasibility checks ---
    preds = []
    for i, j in enumerate(jobs):
        ps = []
        for p in (j.get("after") or []):
            p = str(p)
            if p not in idx:
                state["output"] = {"status": "infeasible",
                                   "reason": "job %s references unknown predecessor %s" % (ids[i], p)}
                return state
            pi = idx[p]
            if pi not in ps:
                ps.append(pi)
        preds.append(ps)

    modes = []  # list of (orig_index, duration, [(ri, units)])
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes") or []):
            d = int(m.get("duration", 1))
            req = m.get("requires") or {}
            ok = True
            rl = []
            for rn, u in req.items():
                u = int(u)
                if rn not in rindex:
                    ok = False
                    break
                ri = rindex[rn]
                if u > maxcap[ri]:
                    ok = False
                    break
                if u > 0:
                    rl.append((ri, u))
            if ok and d >= 1:
                ml.append((mi, d, rl))
        if not ml:
            state["output"] = {"status": "infeasible",
                               "reason": "job %s has no executable mode" % ids[i]}
            return state
        modes.append(ml)

    succ = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        for p in preds[i]:
            succ[p].append(i)
            indeg[i] += 1
    topo = []
    dq = [i for i in range(n) if indeg[i] == 0]
    deg = indeg[:]
    while dq:
        x = dq.pop()
        topo.append(x)
        for s in succ[x]:
            deg[s] -= 1
            if deg[s] == 0:
                dq.append(s)
    if len(topo) != n:
        state["output"] = {"status": "infeasible", "reason": "precedence cycle"}
        return state

    release = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    due = [j.get("due") for j in jobs]
    due = [None if d is None else int(d) for d in due]
    weight = [int(j.get("weight", 0) or 0) for j in jobs]

    dmin = [min(m[1] for m in modes[i]) for i in range(n)]
    dmax = [max(m[1] for m in modes[i]) for i in range(n)]

    # --- horizon and base profile ---
    H = maxbreak + max(release) + sum(dmax) + 5
    base = []
    for ri in range(len(rnames)):
        cal = cals[ri]
        arr = [0] * H
        for k in range(len(cal)):
            a = cal[k][0]
            b = cal[k + 1][0] if k + 1 < len(cal) else H
            if a >= H:
                break
            c = cal[k][1]
            for t in range(a, min(b, H)):
                arr[t] = c
        base.append(arr)

    # --- priority information ---
    es = [0] * n
    for x in topo:
        e = release[x]
        for p in preds[x]:
            v = es[p] + dmin[p]
            if v > e:
                e = v
        es[x] = e
    tail = [0] * n
    for x in reversed(topo):
        m = 0
        for s in succ[x]:
            if tail[s] > m:
                m = tail[s]
        tail[x] = dmin[x] + m
    cp = max(es[i] + tail[i] for i in range(n))
    lst = [cp - tail[i] for i in range(n)]
    INF = 10 ** 9
    dd = [due[i] if due[i] is not None else INF for i in range(n)]
    for x in reversed(topo):
        for p in preds[x]:
            v = dd[x] - dmin[x]
            if v < dd[p]:
                dd[p] = v
    ddk = [min(lst[i], dd[i] - dmin[i]) for i in range(n)]
    wsum = [0.0] * n
    for x in reversed(topo):
        w = float(weight[x]) if due[x] is not None else 0.0
        for s in succ[x]:
            w += wsum[s]
        wsum[x] = w
    wmax = max(wsum) if max(wsum) > 0 else 1.0
    mixk = [ddk[i] - 3.0 * wsum[i] / wmax for i in range(n)]

    rules = [
        [float(v) for v in lst],
        [float(v) for v in ddk],
        [float(v) for v in es],
        mixk,
        [float(lst[i] + es[i]) for i in range(n)],
    ]

    rng = random.Random(12345)

    def decode(keys, mode_noise, beta):
        avail = [a[:] for a in base]
        hlen = [H]
        fin = [0] * n
        st = [0] * n
        md = [0] * n
        rem = [len(preds[i]) for i in range(n)]
        heap = [(keys[i], i) for i in range(n) if rem[i] == 0]
        heapq.heapify(heap)
        cost_t = 0
        mk = 0
        while heap:
            _, x = heapq.heappop(heap)
            est = release[x]
            for p in preds[x]:
                if fin[p] > est:
                    est = fin[p]
            best = None
            ml = modes[x]
            for k in range(len(ml)):
                mi, d, rl = ml[k]
                t = est
                while True:
                    if t + d > hlen[0]:
                        ext = t + d + 50 - hlen[0]
                        for ri in range(len(avail)):
                            avail[ri].extend([maxcap[ri]] * ext)
                        hlen[0] += ext
                    fail = -1
                    tt = t + d - 1
                    while tt >= t:
                        bad = False
                        for ri, u in rl:
                            if avail[ri][tt] < u:
                                bad = True
                                break
                        if bad:
                            fail = tt
                            break
                        tt -= 1
                    if fail < 0:
                        break
                    t = fail + 1
                f = t + d
                sc = f
                if due[x] is not None and f > due[x]:
                    sc += weight[x] * (f - due[x])
                if beta > 0:
                    use = 0.0
                    for ri, u in rl:
                        use += u / float(maxcap[ri] if maxcap[ri] > 0 else 1)
                    sc += beta * use * d
                if mode_noise > 0:
                    sc += rng.random() * mode_noise
                if best is None or sc < best[0]:
                    best = (sc, k, t, d, rl)
            _, k, t, d, rl = best
            for ri, u in rl:
                a = avail[ri]
                for tt in range(t, t + d):
                    a[tt] -= u
            st[x] = t
            fin[x] = t + d
            md[x] = k
            if t + d > mk:
                mk = t + d
            if due[x] is not None and t + d > due[x]:
                cost_t += weight[x] * (t + d - due[x])
            for s in succ[x]:
                rem[s] -= 1
                if rem[s] == 0:
                    heapq.heappush(heap, (keys[s], s))
        return mk + cost_t, st, md

    best_cost = None
    best_sol = None
    best_keys = None

    def consider(keys, mn, beta):
        nonlocal best_cost, best_sol, best_keys
        c, st, md = decode(keys, mn, beta)
        if best_cost is None or c < best_cost:
            best_cost = c
            best_sol = (st, md)
            best_keys = keys
        return c

    for rk in rules:
        consider(rk, 0, 0)
        if time.process_time() - t_start > budget:
            break
    for rk in rules:
        if time.process_time() - t_start > budget:
            break
        consider(rk, 0, 0.3)

    scale = max(1.0, cp / 10.0)
    while time.process_time() - t_start < budget:
        r = rng.random()
        if r < 0.65 and best_keys is not None:
            src = best_keys
            sc = scale * rng.choice([0.1, 0.3, 0.6, 1.0])
        else:
            src = rng.choice(rules)
            sc = scale * rng.choice([0.3, 1.0, 2.0])
        keys = [src[i] + rng.gauss(0, sc) for i in range(n)]
        mn = 0 if rng.random() < 0.7 else rng.choice([1, 2, 4])
        beta = 0 if rng.random() < 0.6 else rng.choice([0.2, 0.5, 1.0])
        consider(keys, mn, beta)

    st, md = best_sol
    sched = {}
    for i in range(n):
        sched[ids[i]] = {"start": int(st[i]), "mode": int(modes[i][md[i]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    return state

import time, random, heapq, math


def solve(state, params):
    T0 = time.process_time()
    BUDGET = 0.75

    def elapsed():
        return time.process_time() - T0

    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs_in = inp.get("jobs") or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    caps_last = []
    lastbp = 0
    for r in rnames:
        cal = (resources[r] or {}).get("calendar") or [[0, 0]]
        cal = sorted([(int(a[0]), int(a[1])) for a in cal])
        cals.append(cal)
        caps_last.append(cal[-1][1])
        lastbp = max(lastbp, cal[-1][0])
    ids = []
    seen = {}
    for jb in jobs_in:
        jid = str(jb.get("id"))
        if jid in seen:
            continue
        seen[jid] = len(ids)
        ids.append(jid)
    jobs = [None] * len(ids)
    for jb in jobs_in:
        jid = str(jb.get("id"))
        if jobs[seen[jid]] is None:
            jobs[seen[jid]] = jb
    n = len(ids)

    def infeas(msg):
        state["output"] = {"status": "infeasible", "reason": msg}
        return state

    preds = [[] for _ in range(n)]
    succs = [[] for _ in range(n)]
    for j, jb in enumerate(jobs):
        ps = set()
        for p in (jb.get("after") or []):
            p = str(p)
            if p not in seen:
                return infeas("job %s references unknown predecessor %s" % (ids[j], p))
            ps.add(seen[p])
        if j in ps:
            return infeas("precedence cycle at job %s" % ids[j])
        preds[j] = sorted(ps)
        for p in ps:
            succs[p].append(j)
    indeg = [len(preds[j]) for j in range(n)]
    q = [j for j in range(n) if indeg[j] == 0]
    topo = []
    while q:
        j = q.pop()
        topo.append(j)
        for s in succs[j]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    if len(topo) < n:
        return infeas("precedence relation has a cycle")
    modes = []
    rel = []
    due = []
    wt = []
    for j, jb in enumerate(jobs):
        ml = []
        for mi, md in enumerate(jb.get("modes") or []):
            d = max(1, int(md.get("duration", 1)))
            req = []
            ok = True
            for rn, u in (md.get("requires") or {}).items():
                u = int(u)
                if rn not in ridx:
                    ok = False
                    break
                if u <= 0:
                    continue
                if u > caps_last[ridx[rn]]:
                    ok = False
                    break
                req.append((ridx[rn], u))
            if ok:
                ml.append((d, req, mi))
        if not ml:
            return infeas("job %s has no executable mode" % ids[j])
        modes.append(ml)
        rel.append(max(0, int(jb.get("release") or 0)))
        dd = jb.get("due")
        due.append(None if dd is None else int(dd))
        wt.append(max(0, int(jb.get("weight") or 0)))
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state

    nr = len(rnames)
    maxd = [max(m[0] for m in modes[j]) for j in range(n)]
    mind = [min(m[0] for m in modes[j]) for j in range(n)]
    H = max(lastbp, max(rel)) + sum(maxd) + 2 * max(maxd) + 10
    base = []
    for ri in range(nr):
        cal = cals[ri]
        arr = [0] * H
        for k, (t, c) in enumerate(cal):
            e = cal[k + 1][0] if k + 1 < len(cal) else H
            t = max(0, min(t, H))
            e = max(t, min(e, H))
            arr[t:e] = [c] * (e - t)
        base.append(arr)
    tardy = [due[j] is not None and wt[j] > 0 for j in range(n)]
    nm = [len(modes[j]) for j in range(n)]
    topo_pos = [0] * n
    for k, j in enumerate(topo):
        topo_pos[j] = k

    # ---------------- serial SGS with prefix reuse and early abort -------------
    def sgs(order, mvec, pre=0, pstart=None, pmode=None, limit=None):
        av = [a[:] for a in base]
        start = [0] * n
        fin = [0] * n
        mch = [0] * n
        mk = 0
        td = 0
        for k in range(pre):
            j = order[k]
            t = pstart[j]
            m = pmode[j]
            d, req, _ = modes[j][m]
            e = t + d
            for (r, qq) in req:
                a = av[r]
                a[t:e] = [x - qq for x in a[t:e]]
            start[j] = t
            fin[j] = e
            mch[j] = m
            if e > mk:
                mk = e
            if tardy[j] and e > due[j]:
                td += wt[j] * (e - due[j])
        if limit is not None and mk + td > limit:
            return None
        for k in range(pre, len(order)):
            j = order[k]
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            mm = mvec[j]
            cand = range(nm[j]) if mm < 0 else (mm,)
            bt = -1
            bm = -1
            bf = 0
            bkey = None
            for m in cand:
                d, req, _ = modes[j][m]
                t = est
                if req:
                    while True:
                        e = t + d
                        moved = False
                        for (r, qq) in req:
                            a = av[r]
                            if min(a[t:e]) < qq:
                                tt = e - 1
                                while a[tt] >= qq:
                                    tt -= 1
                                t = tt + 1
                                moved = True
                                break
                        if not moved:
                            break
                f = t + d
                if mm < 0:
                    c = f - mk if f > mk else 0
                    if tardy[j] and f > due[j]:
                        c += wt[j] * (f - due[j])
                    key = (c, f, sum(qq for _, qq in req) * d)
                    if bkey is None or key < bkey:
                        bkey = key
                        bt = t
                        bm = m
                        bf = f
                else:
                    bt = t
                    bm = m
                    bf = f
            d, req, _ = modes[j][bm]
            t = bt
            e = bf
            for (r, qq) in req:
                a = av[r]
                a[t:e] = [x - qq for x in a[t:e]]
            start[j] = t
            fin[j] = e
            mch[j] = bm
            if e > mk:
                mk = e
            if tardy[j] and e > due[j]:
                td += wt[j] * (e - due[j])
            if limit is not None and mk + td > limit:
                return None
        return (mk + td, start, mch)

    # ---------------- forward-backward improvement -------------
    def fbi_order(st, mc):
        fin = [st[j] + modes[j][mc[j]][0] for j in range(n)]
        C = max(fin)
        ordb = sorted(range(n), key=lambda j: (-fin[j], -topo_pos[j]))
        av = [a[:] for a in base]
        bst = [0] * n
        for j in ordb:
            d, req, _ = modes[j][mc[j]]
            lim = C
            for s in succs[j]:
                if bst[s] < lim:
                    lim = bst[s]
            t = lim - d
            while True:
                if t < rel[j] or t < 0:
                    return None
                bad = -1
                for (r, qq) in req:
                    a = av[r]
                    if min(a[t:t + d]) < qq:
                        k = t
                        while a[k] >= qq:
                            k += 1
                        bad = k
                        break
                if bad < 0:
                    break
                t = bad - d
            bst[j] = t
            for (r, qq) in req:
                a = av[r]
                a[t:t + d] = [x - qq for x in a[t:t + d]]
        return sorted(range(n), key=lambda j: (bst[j], topo_pos[j]))

    def improve_fbi(c, st, mc, rounds=3):
        improved = False
        for _ in range(rounds):
            o = fbi_order(st, mc)
            if o is None:
                break
            res = sgs(o, mc, limit=c - 1)
            if res is None:
                break
            c, st, mc = res
            improved = True
        return improved, c, st, mc

    # ---------------- priority rules -------------
    tail = [0] * n
    for j in reversed(topo):
        b = 0
        for s in succs[j]:
            if tail[s] > b:
                b = tail[s]
        tail[j] = b + mind[j]
    head = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            v = head[p] + mind[p]
            if v > e:
                e = v
        head[j] = e
    cp = max(head[j] + tail[j] for j in range(n))
    lft = [cp - tail[j] + mind[j] for j in range(n)]
    BIG = 10 ** 9
    dlf = [BIG] * n
    for j in reversed(topo):
        v = due[j] if tardy[j] else BIG
        for s in succs[j]:
            x = dlf[s] - mind[s]
            if x < v:
                v = x
        dlf[j] = v
    nsucc = [0] * n
    for j in reversed(topo):
        nsucc[j] = len(succs[j]) + sum(nsucc[s] for s in succs[j])
    Wd = [0.0] * n
    for j in reversed(topo):
        Wd[j] = (wt[j] if tardy[j] else 0) + 0.5 * sum(Wd[s] for s in succs[j])
    maxW = max(Wd) if max(Wd) > 0 else 1.0
    avgp = sum(mind) / float(n)
    sk = [min(lft[j], dlf[j]) for j in range(n)]

    raw_rules = []
    raw_rules.append([(lft[j], j) for j in range(n)])
    raw_rules.append([(sk[j], lft[j]) for j in range(n)])
    raw_rules.append([(sk[j], rel[j]) for j in range(n)])
    raw_rules.append([(-nsucc[j], lft[j]) for j in range(n)])
    raw_rules.append([(max(rel[j], head[j]), sk[j]) for j in range(n)])
    raw_rules.append([(-tail[j], sk[j]) for j in range(n)])
    atc = []
    for j in range(n):
        slack = max(0, dlf[j] - head[j] - mind[j]) if dlf[j] < BIG else BIG
        v = 0.0 if slack >= BIG else (Wd[j] + 1e-3) / mind[j] * math.exp(-slack / (2.0 * avgp))
        atc.append((-v, sk[j]))
    raw_rules.append(atc)
    raw_rules.append([(sk[j] - 0.5 * cp * Wd[j] / maxW, lft[j]) for j in range(n)])
    raw_rules.append([(head[j] + 0.5 * min(lft[j], dlf[j] if dlf[j] < BIG else lft[j]), j) for j in range(n)])
    rules = []
    for rr in raw_rules:
        ordr = sorted(range(n), key=lambda j: rr[j])
        rk = [0] * n
        for p, j in enumerate(ordr):
            rk[j] = float(p)
        rules.append(rk)

    def make_order(prio, noise=0.0, rng=None):
        ind = [len(preds[j]) for j in range(n)]
        h = []
        for j in range(n):
            if ind[j] == 0:
                key = prio[j] + (rng.random() * noise if noise else 0.0)
                heapq.heappush(h, (key, j))
        out = []
        while h:
            _, j = heapq.heappop(h)
            out.append(j)
            for s in succs[j]:
                ind[s] -= 1
                if ind[s] == 0:
                    key = prio[s] + (rng.random() * noise if noise else 0.0)
                    heapq.heappush(h, (key, s))
        return out

    rng = random.Random(12345)
    best = None
    pool = []

    def consider(order, res):
        nonlocal best
        c, st, mc = res
        o2 = sorted(order, key=lambda j: (st[j], topo_pos[j]))
        pool.append((c, o2, mc[:], st[:]))
        if best is None or c < best[0]:
            best = (c, o2, mc[:], st[:])

    allgreedy = [-1] * n
    fastm = [min(range(nm[j]), key=lambda m: (modes[j][m][0], sum(qq for _, qq in modes[j][m][1]))) for j in range(n)]
    rule_best = []
    for ri, pr in enumerate(rules):
        o = make_order(pr)
        r1 = sgs(o, allgreedy)
        consider(o, r1)
        r2 = sgs(o, fastm)
        consider(o, r2)
        rule_best.append(min(r1[0], r2[0]))
        if elapsed() > BUDGET * 0.3:
            break
    good_rule = min(range(len(rule_best)), key=lambda i: rule_best[i])

    # ---------------- biased random sampling -------------
    t_sample_end = BUDGET * 0.22
    it = 0
    while elapsed() < t_sample_end:
        it += 1
        if rng.random() < 0.55:
            pr = rules[good_rule]
        else:
            pr = rules[rng.randrange(len(rules))]
        o = make_order(pr, noise=n * 0.4 * rng.random(), rng=rng)
        mvv = allgreedy if rng.random() < 0.8 else fastm
        res = sgs(o, mvv, limit=best[0] * 1.15)
        if res is not None:
            consider(o, res)
    pool.sort(key=lambda x: x[0])

    # ---------------- FBI on top pool entries -------------
    seen_c = set()
    cnt = 0
    for ent in list(pool[:12]):
        if cnt >= 5 or elapsed() > BUDGET * 0.32:
            break
        if ent[0] in seen_c:
            continue
        seen_c.add(ent[0])
        cnt += 1
        imp, c2, st2, mc2 = improve_fbi(ent[0], ent[3], ent[2])
        if imp:
            o2 = sorted(range(n), key=lambda j: (st2[j], topo_pos[j]))
            consider(o2, (c2, st2, mc2))
    pool.sort(key=lambda x: x[0])
    pool = pool[:20]

    # ---------------- simulated annealing -------------
    cur_c, cur_o, cur_m, cur_s = best[0], best[1][:], best[2][:], best[3][:]
    multi = [j for j in range(n) if nm[j] > 1]
    T_start = max(0.5, 0.02 * best[0])
    t_ls0 = elapsed()
    total = max(1e-6, BUDGET - t_ls0)
    noimp = 0
    restarts = 0
    last_fbi_best = best[0]

    def pick_bad(st, mc):
        fin = [st[x] + modes[x][mc[x]][0] for x in range(n)]
        mk = max(fin)
        ws = []
        tot = 0.0
        for x in range(n):
            w = 0.0
            if tardy[x] and fin[x] > due[x]:
                w += wt[x] * (fin[x] - due[x])
            if fin[x] == mk:
                w += 1.0 + 0.05 * mk
            if w > 0:
                ws.append((x, w))
                tot += w
        if not ws:
            return rng.randrange(n), fin
        r = rng.random() * tot
        for x, w in ws:
            r -= w
            if r <= 0:
                return x, fin
        return ws[-1][0], fin

    while True:
        el = elapsed()
        if el >= BUDGET:
            break
        frac = (el - t_ls0) / total
        T = T_start * (1 - frac) + 0.05
        o = cur_o[:]
        mv = cur_m[:]
        rmv = rng.random()
        firstpos = n
        did_shift = False
        if multi and rmv < 0.28:
            if rng.random() < 0.4:
                j, _ = pick_bad(cur_s, cur_m)
                if nm[j] < 2:
                    j = rng.choice(multi)
            else:
                j = rng.choice(multi)
            if rng.random() < 0.2:
                mv[j] = -1
            else:
                m = rng.randrange(nm[j] - 1)
                if m >= mv[j]:
                    m += 1
                mv[j] = m
            firstpos = o.index(j)
            if rng.random() < 0.25:
                rmv = 0.5
        if rmv >= 0.28:
            did_shift = True
            if rng.random() < 0.45:
                j, fin = pick_bad(cur_s, cur_m)
                while rng.random() < 0.45:
                    tight = [p for p in preds[j] if fin[p] >= cur_s[j]]
                    if not tight:
                        break
                    j = rng.choice(tight)
                early = True
            else:
                j = rng.randrange(n)
                early = False
            i = o.index(j)
            o.pop(i)
            pos = {x: k for k, x in enumerate(o)}
            lo = 0
            for p in preds[j]:
                if pos[p] + 1 > lo:
                    lo = pos[p] + 1
            hi = len(o)
            for s in succs[j]:
                if pos[s] < hi:
                    hi = pos[s]
            if early:
                hi = min(hi, i)
            if hi < lo:
                hi = lo
            if rng.random() < 0.5:
                np_ = min(max(i + rng.randint(-8, 8), lo), hi)
            else:
                np_ = rng.randint(lo, hi)
            o.insert(np_, j)
            firstpos = min(firstpos, i, np_)
        if did_shift and o == cur_o and mv == cur_m:
            continue
        u = rng.random()
        thr = cur_c - T * math.log(max(u, 1e-12))
        res = sgs(o, mv, pre=firstpos, pstart=cur_s, pmode=cur_m, limit=thr)
        if res is None:
            noimp += 1
        else:
            c, st, mc = res
            cur_c = c
            cur_o = sorted(o, key=lambda x: (st[x], topo_pos[x]))
            cur_m = mc
            cur_s = st
            if c < best[0]:
                best = (c, cur_o[:], cur_m[:], cur_s[:])
                noimp = 0
                if c < last_fbi_best and elapsed() < BUDGET - 0.02:
                    last_fbi_best = c
                    imp, c2, st2, mc2 = improve_fbi(c, st, mc, 2)
                    if imp:
                        o2 = sorted(range(n), key=lambda x: (st2[x], topo_pos[x]))
                        best = (c2, o2[:], mc2[:], st2[:])
                        cur_c, cur_o, cur_m, cur_s = c2, o2, mc2[:], st2[:]
                        last_fbi_best = c2
            else:
                noimp += 1
        if noimp > 300 + 3 * n:
            noimp = 0
            restarts += 1
            if restarts % 2 or not pool:
                src = best
            else:
                src = pool[rng.randrange(min(5, len(pool)))]
            cur_c, cur_o, cur_m, cur_s = src[0], src[1][:], src[2][:], src[3][:]

    c, o, mc, st = best

    # ---------------- validation & fallback -------------
    def valid(st, mc):
        use = [[0] * H for _ in range(nr)]
        for j in range(n):
            if st[j] < rel[j] or st[j] < 0:
                return False
            d = modes[j][mc[j]][0]
            if st[j] + d > H:
                return False
            for p in preds[j]:
                if st[j] < st[p] + modes[p][mc[p]][0]:
                    return False
            for (r, qq) in modes[j][mc[j]][1]:
                a = use[r]
                for t in range(st[j], st[j] + d):
                    a[t] += qq
        for r in range(nr):
            a = use[r]
            b = base[r]
            for t in range(H):
                if a[t] > b[t]:
                    return False
        return True

    if not valid(st, mc):
        res = sgs(topo, fastm)
        c, st, mc = res
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": int(st[j]), "mode": int(modes[j][mc[j]][2])}
    state["output"] = {"status": "ok", "schedule": sched}
    state["cost"] = c
    return state

import time, random, heapq, math


def solve(state, params):
    T0 = time.process_time()
    BUDGET = 0.8

    def elapsed():
        return time.process_time() - T0

    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs_in = inp.get("jobs") or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    caps_last = []
    lastbp = 0
    for r in rnames:
        cal = (resources[r] or {}).get("calendar") or [[0, 0]]
        cal = sorted([(int(a[0]), int(a[1])) for a in cal])
        cals.append(cal)
        caps_last.append(cal[-1][1])
        lastbp = max(lastbp, cal[-1][0])
    ids = []
    seen = {}
    for jb in jobs_in:
        jid = str(jb.get("id"))
        if jid in seen:
            continue
        seen[jid] = len(ids)
        ids.append(jid)
    jobs = [None] * len(ids)
    for jb in jobs_in:
        jid = str(jb.get("id"))
        if jobs[seen[jid]] is None:
            jobs[seen[jid]] = jb
    n = len(ids)

    def infeas(msg):
        state["output"] = {"status": "infeasible", "reason": msg}
        return state

    preds = [[] for _ in range(n)]
    succs = [[] for _ in range(n)]
    for j, jb in enumerate(jobs):
        ps = set()
        for p in (jb.get("after") or []):
            p = str(p)
            if p not in seen:
                return infeas("job %s references unknown predecessor %s" % (ids[j], p))
            ps.add(seen[p])
        if j in ps:
            return infeas("precedence cycle at job %s" % ids[j])
        preds[j] = sorted(ps)
        for p in ps:
            succs[p].append(j)
    indeg = [len(preds[j]) for j in range(n)]
    q = [j for j in range(n) if indeg[j] == 0]
    topo = []
    while q:
        j = q.pop()
        topo.append(j)
        for s in succs[j]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    if len(topo) < n:
        return infeas("precedence relation has a cycle")
    modes = []
    rel = []
    due = []
    wt = []
    for j, jb in enumerate(jobs):
        ml = []
        for mi, md in enumerate(jb.get("modes") or []):
            d = max(1, int(md.get("duration", 1)))
            req = []
            ok = True
            for rn, u in (md.get("requires") or {}).items():
                u = int(u)
                if rn not in ridx:
                    ok = False
                    break
                if u <= 0:
                    continue
                if u > caps_last[ridx[rn]]:
                    ok = False
                    break
                req.append((ridx[rn], u))
            if ok:
                usen = 0.0
                raw = 0
                for (r, u) in req:
                    usen += u * d / (caps_last[r] + 1.0)
                    raw += u * d
                ml.append((d, req, mi, usen, raw))
        if not ml:
            return infeas("job %s has no executable mode" % ids[j])
        modes.append(ml)
        rel.append(max(0, int(jb.get("release") or 0)))
        dd = jb.get("due")
        due.append(None if dd is None else int(dd))
        wt.append(max(0, int(jb.get("weight") or 0)))
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state

    nr = len(rnames)
    maxd = [max(m[0] for m in modes[j]) for j in range(n)]
    mind = [min(m[0] for m in modes[j]) for j in range(n)]
    H = max(lastbp, max(rel)) + sum(maxd) + 2 * max(maxd) + 10
    base = []
    for ri in range(nr):
        cal = cals[ri]
        arr = [0] * H
        for k, (t, c) in enumerate(cal):
            e = cal[k + 1][0] if k + 1 < len(cal) else H
            t = max(0, min(t, H))
            e = max(t, min(e, H))
            arr[t:e] = [c] * (e - t)
        base.append(arr)
    tardy = [due[j] is not None and wt[j] > 0 for j in range(n)]
    nm = [len(modes[j]) for j in range(n)]
    topo_pos = [0] * n
    for k, j in enumerate(topo):
        topo_pos[j] = k
    predset = [set(preds[j]) for j in range(n)]

    # ---------------- serial SGS: prefix reuse, early abort, 2 greedy mode policies -------------
    def sgs(order, mvec, pre=0, pstart=None, pmode=None, limit=None):
        av = [a[:] for a in base]
        start = [0] * n
        fin = [0] * n
        mch = [0] * n
        mk = 0
        td = 0
        for k in range(pre):
            j = order[k]
            t = pstart[j]
            m = pmode[j]
            md = modes[j][m]
            d = md[0]
            e = t + d
            for (r, qq) in md[1]:
                a = av[r]
                a[t:e] = [x - qq for x in a[t:e]]
            start[j] = t
            fin[j] = e
            mch[j] = m
            if e > mk:
                mk = e
            if tardy[j] and e > due[j]:
                td += wt[j] * (e - due[j])
        if limit is not None and mk + td > limit:
            return None
        for k in range(pre, len(order)):
            j = order[k]
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            mm = mvec[j]
            cand = range(nm[j]) if mm < 0 else (mm,)
            bt = -1
            bm = -1
            bf = 0
            bkey = None
            mj = modes[j]
            for m in cand:
                md = mj[m]
                d = md[0]
                req = md[1]
                t = est
                if req:
                    while True:
                        e = t + d
                        moved = False
                        for (r, qq) in req:
                            a = av[r]
                            if min(a[t:e]) < qq:
                                tt = e - 1
                                while a[tt] >= qq:
                                    tt -= 1
                                t = tt + 1
                                moved = True
                                break
                        if not moved:
                            break
                f = t + d
                if mm < 0:
                    c = f - mk if f > mk else 0
                    if tardy[j] and f > due[j]:
                        c += wt[j] * (f - due[j])
                    if mm == -1:
                        key = (c, f, md[4])
                    else:
                        key = (c + f + 0.3 * md[3], f, 0)
                    if bkey is None or key < bkey:
                        bkey = key
                        bt = t
                        bm = m
                        bf = f
                else:
                    bt = t
                    bm = m
                    bf = f
            md = mj[bm]
            t = bt
            e = bf
            for (r, qq) in md[1]:
                a = av[r]
                a[t:e] = [x - qq for x in a[t:e]]
            start[j] = t
            fin[j] = e
            mch[j] = bm
            if e > mk:
                mk = e
            if tardy[j] and e > due[j]:
                td += wt[j] * (e - due[j])
            if limit is not None and mk + td > limit:
                return None
        return (mk + td, start, mch)

    # ---------------- forward-backward improvement -------------
    def fbi_order(st, mc):
        fin = [st[j] + modes[j][mc[j]][0] for j in range(n)]
        C = max(fin)
        ordb = sorted(range(n), key=lambda j: (-fin[j], -topo_pos[j]))
        av = [a[:] for a in base]
        bst = [0] * n
        for j in ordb:
            md = modes[j][mc[j]]
            d = md[0]
            req = md[1]
            lim = C
            for s in succs[j]:
                if bst[s] < lim:
                    lim = bst[s]
            t = lim - d
            while True:
                if t < rel[j] or t < 0:
                    return None
                bad = -1
                for (r, qq) in req:
                    a = av[r]
                    if min(a[t:t + d]) < qq:
                        k = t
                        while a[k] >= qq:
                            k += 1
                        bad = k
                        break
                if bad < 0:
                    break
                t = bad - d
            bst[j] = t
            for (r, qq) in req:
                a = av[r]
                a[t:t + d] = [x - qq for x in a[t:t + d]]
        return sorted(range(n), key=lambda j: (bst[j], topo_pos[j]))

    def improve_fbi(c, st, mc, rounds=3):
        improved = False
        for _ in range(rounds):
            o = fbi_order(st, mc)
            if o is None:
                break
            res = sgs(o, mc, limit=c - 1)
            if res is None:
                break
            c, st, mc = res
            improved = True
        return improved, c, st, mc

    # ---------------- priority rules -------------
    tail = [0] * n
    for j in reversed(topo):
        b = 0
        for s in succs[j]:
            if tail[s] > b:
                b = tail[s]
        tail[j] = b + mind[j]
    head = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            v = head[p] + mind[p]
            if v > e:
                e = v
        head[j] = e
    cp = max(head[j] + tail[j] for j in range(n))
    lft = [cp - tail[j] + mind[j] for j in range(n)]
    BIG = 10 ** 9
    dlf = [BIG] * n
    for j in reversed(topo):
        v = due[j] if tardy[j] else BIG
        for s in succs[j]:
            x = dlf[s] - mind[s]
            if x < v:
                v = x
        dlf[j] = v
    nsucc = [0] * n
    for j in reversed(topo):
        nsucc[j] = len(succs[j]) + sum(nsucc[s] for s in succs[j])
    Wd = [0.0] * n
    for j in reversed(topo):
        Wd[j] = (wt[j] if tardy[j] else 0) + 0.5 * sum(Wd[s] for s in succs[j])
    maxW = max(Wd) if max(Wd) > 0 else 1.0
    avgp = sum(mind) / float(n)
    sk = [min(lft[j], dlf[j]) for j in range(n)]

    raw_rules = []
    raw_rules.append([(lft[j], j) for j in range(n)])
    raw_rules.append([(sk[j], lft[j]) for j in range(n)])
    raw_rules.append([(sk[j], rel[j]) for j in range(n)])
    raw_rules.append([(-nsucc[j], lft[j]) for j in range(n)])
    raw_rules.append([(max(rel[j], head[j]), sk[j]) for j in range(n)])
    raw_rules.append([(-tail[j], sk[j]) for j in range(n)])
    atc = []
    for j in range(n):
        slack = max(0, dlf[j] - head[j] - mind[j]) if dlf[j] < BIG else BIG
        v = 0.0 if slack >= BIG else (Wd[j] + 1e-3) / mind[j] * math.exp(-slack / (2.0 * avgp))
        atc.append((-v, sk[j]))
    raw_rules.append(atc)
    raw_rules.append([(sk[j] - 0.5 * cp * Wd[j] / maxW, lft[j]) for j in range(n)])
    raw_rules.append([(head[j] + 0.5 * min(lft[j], dlf[j] if dlf[j] < BIG else lft[j]), j) for j in range(n)])
    raw_rules.append([(-(Wd[j] / float(mind[j])), sk[j]) for j in range(n)])
    raw_rules.append([(dlf[j], head[j], lft[j]) for j in range(n)])
    rules = []
    for rr in raw_rules:
        ordr = sorted(range(n), key=lambda j: rr[j])
        rk = [0] * n
        for p, j in enumerate(ordr):
            rk[j] = float(p)
        rules.append(rk)

    def make_order(prio, noise=0.0, rng=None):
        ind = [len(preds[j]) for j in range(n)]
        h = []
        for j in range(n):
            if ind[j] == 0:
                key = prio[j] + (rng.random() * noise if noise else 0.0)
                heapq.heappush(h, (key, j))
        out = []
        while h:
            _, j = heapq.heappop(h)
            out.append(j)
            for s in succs[j]:
                ind[s] -= 1
                if ind[s] == 0:
                    key = prio[s] + (rng.random() * noise if noise else 0.0)
                    heapq.heappush(h, (key, s))
        return out

    rng = random.Random(12345)
    best = None
    pool = []

    def consider(order, res):
        nonlocal best
        c, st, mc = res
        o2 = sorted(order, key=lambda j: (st[j], topo_pos[j]))
        pool.append((c, o2, mc[:], st[:]))
        if best is None or c < best[0]:
            best = (c, o2, mc[:], st[:])

    g1 = [-1] * n
    g2 = [-2] * n
    fastm = [min(range(nm[j]), key=lambda m: (modes[j][m][0], modes[j][m][4])) for j in range(n)]
    policies = [g1, g2, fastm]
    rule_best = []
    for ri, pr in enumerate(rules):
        o = make_order(pr)
        bb = None
        for mvv in policies:
            r1 = sgs(o, mvv)
            consider(o, r1)
            if bb is None or r1[0] < bb:
                bb = r1[0]
        rule_best.append(bb)
        if elapsed() > BUDGET * 0.25:
            break
    rank_rules = sorted(range(len(rule_best)), key=lambda i: rule_best[i])
    good_rules = rank_rules[:3]

    # ---------------- biased random sampling -------------
    t_sample_end = BUDGET * 0.22
    while elapsed() < t_sample_end:
        x = rng.random()
        if x < 0.6:
            pr = rules[rng.choice(good_rules)]
        else:
            pr = rules[rng.randrange(len(rules))]
        o = make_order(pr, noise=n * 0.4 * rng.random(), rng=rng)
        y = rng.random()
        mvv = g1 if y < 0.45 else (g2 if y < 0.85 else fastm)
        res = sgs(o, mvv, limit=best[0] * 1.15)
        if res is not None:
            consider(o, res)
    pool.sort(key=lambda x: x[0])

    # ---------------- FBI on top pool entries -------------
    seen_c = set()
    cnt = 0
    for ent in list(pool[:14]):
        if cnt >= 6 or elapsed() > BUDGET * 0.32:
            break
        if ent[0] in seen_c:
            continue
        seen_c.add(ent[0])
        cnt += 1
        imp, c2, st2, mc2 = improve_fbi(ent[0], ent[3], ent[2])
        if imp:
            o2 = sorted(range(n), key=lambda j: (st2[j], topo_pos[j]))
            consider(o2, (c2, st2, mc2))
    pool.sort(key=lambda x: x[0])
    elite = []
    sc = set()
    for ent in pool:
        if ent[0] in sc:
            continue
        sc.add(ent[0])
        elite.append(ent)
        if len(elite) >= 8:
            break
    pool = elite

    # ---------------- simulated annealing -------------
    cur_c, cur_o, cur_m, cur_s = best[0], best[1][:], best[2][:], best[3][:]
    multi = [j for j in range(n) if nm[j] > 1]
    T_start = max(0.5, 0.02 * best[0])
    t_ls0 = elapsed()
    total = max(1e-6, BUDGET - t_ls0)
    noimp = 0
    restarts = 0
    accepted = 0
    last_fbi_best = best[0]

    def pick_bad(st, mc):
        fin = [st[x] + modes[x][mc[x]][0] for x in range(n)]
        mk = max(fin)
        ws = []
        tot = 0.0
        for x in range(n):
            w = 0.0
            if tardy[x] and fin[x] > due[x]:
                w += wt[x] * (fin[x] - due[x])
            if fin[x] == mk:
                w += 1.0 + 0.05 * mk
            if w > 0:
                ws.append((x, w))
                tot += w
        if not ws:
            return rng.randrange(n), fin
        r = rng.random() * tot
        for x, w in ws:
            r -= w
            if r <= 0:
                return x, fin
        return ws[-1][0], fin

    while True:
        el = elapsed()
        if el >= BUDGET:
            break
        frac = (el - t_ls0) / total
        T = T_start * (1 - frac) * (1 - frac) + 0.05
        o = cur_o[:]
        mv = cur_m[:]
        rmv = rng.random()
        firstpos = n
        did_shift = False
        if multi and rmv < 0.25:
            if rng.random() < 0.4:
                j, _ = pick_bad(cur_s, cur_m)
                if nm[j] < 2:
                    j = rng.choice(multi)
            else:
                j = rng.choice(multi)
            z = rng.random()
            if z < 0.12:
                mv[j] = -1
            elif z < 0.22:
                mv[j] = -2
            else:
                m = rng.randrange(nm[j] - 1)
                if m >= mv[j]:
                    m += 1
                mv[j] = m
            firstpos = o.index(j)
            if rng.random() < 0.25:
                rmv = 0.5
        if 0.25 <= rmv < 0.35 and n > 1:
            # adjacent precedence-safe swap
            did_shift = True
            i = rng.randrange(n - 1)
            a1 = o[i]
            a2 = o[i + 1]
            if a1 in predset[a2]:
                continue
            o[i], o[i + 1] = a2, a1
            firstpos = min(firstpos, i)
        elif rmv >= 0.35 or (rmv >= 0.25 and n <= 1):
            did_shift = True
            pull = False
            if rng.random() < 0.5:
                j, fin = pick_bad(cur_s, cur_m)
                while rng.random() < 0.45:
                    tight = [p for p in preds[j] if fin[p] >= cur_s[j]]
                    if not tight:
                        break
                    j = rng.choice(tight)
                early = True
                pull = rng.random() < 0.3
            else:
                j = rng.randrange(n)
                early = False
            i = o.index(j)
            o.pop(i)
            pos = {x: k for k, x in enumerate(o)}
            lo = 0
            for p in preds[j]:
                if pos[p] + 1 > lo:
                    lo = pos[p] + 1
            hi = len(o)
            for s in succs[j]:
                if pos[s] < hi:
                    hi = pos[s]
            if early:
                hi = min(hi, i)
            if hi < lo:
                hi = lo
            if pull:
                np_ = lo
            elif rng.random() < 0.5:
                np_ = min(max(i + rng.randint(-8, 8), lo), hi)
            else:
                np_ = rng.randint(lo, hi)
            o.insert(np_, j)
            firstpos = min(firstpos, i, np_)
        if did_shift and o == cur_o and mv == cur_m:
            continue
        u = rng.random()
        thr = cur_c - T * math.log(max(u, 1e-12))
        res = sgs(o, mv, pre=firstpos, pstart=cur_s, pmode=cur_m, limit=thr)
        if res is None:
            noimp += 1
        else:
            c, st, mc = res
            cur_c = c
            cur_o = sorted(o, key=lambda x: (st[x], topo_pos[x]))
            cur_m = mc
            cur_s = st
            accepted += 1
            if c < best[0]:
                best = (c, cur_o[:], cur_m[:], cur_s[:])
                noimp = 0
                if c < last_fbi_best and elapsed() < BUDGET - 0.02:
                    last_fbi_best = c
                    imp, c2, st2, mc2 = improve_fbi(c, st, mc, 2)
                    if imp:
                        o2 = sorted(range(n), key=lambda x: (st2[x], topo_pos[x]))
                        best = (c2, o2[:], mc2[:], st2[:])
                        cur_c, cur_o, cur_m, cur_s = c2, o2, mc2[:], st2[:]
                        last_fbi_best = c2
            else:
                noimp += 1
                if accepted % 40 == 0 and cur_c <= best[0] * 1.03 and elapsed() < BUDGET - 0.02:
                    imp, c2, st2, mc2 = improve_fbi(cur_c, cur_s, cur_m, 1)
                    if imp:
                        o2 = sorted(range(n), key=lambda x: (st2[x], topo_pos[x]))
                        cur_c, cur_o, cur_m, cur_s = c2, o2, mc2[:], st2[:]
                        if c2 < best[0]:
                            best = (c2, o2[:], mc2[:], st2[:])
                            noimp = 0
        if noimp > 300 + 3 * n:
            noimp = 0
            restarts += 1
            if restarts % 2 or not pool:
                src = best
            else:
                src = pool[rng.randrange(min(5, len(pool)))]
            cur_c, cur_o, cur_m, cur_s = src[0], src[1][:], src[2][:], src[3][:]

    c, o, mc, st = best

    # ---------------- validation & fallback -------------
    def valid(st, mc):
        use = [[0] * H for _ in range(nr)]
        for j in range(n):
            if st[j] < rel[j] or st[j] < 0:
                return False
            d = modes[j][mc[j]][0]
            if st[j] + d > H:
                return False
            for p in preds[j]:
                if st[j] < st[p] + modes[p][mc[p]][0]:
                    return False
            for (r, qq) in modes[j][mc[j]][1]:
                a = use[r]
                for t in range(st[j], st[j] + d):
                    a[t] += qq
        for r in range(nr):
            a = use[r]
            b = base[r]
            for t in range(H):
                if a[t] > b[t]:
                    return False
        return True

    if not valid(st, mc):
        res = sgs(topo, fastm)
        c, st, mc = res
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": int(st[j]), "mode": int(modes[j][mc[j]][2])}
    state["output"] = {"status": "ok", "schedule": sched}
    state["cost"] = c
    return state

import time, random, heapq, math


def solve(state, params):
    T0 = time.process_time()
    BUDGET = 0.78

    def elapsed():
        return time.process_time() - T0

    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs_in = inp.get("jobs") or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    caps_last = []
    lastbp = 0
    for r in rnames:
        cal = (resources[r] or {}).get("calendar") or [[0, 0]]
        cal = sorted([(int(a[0]), int(a[1])) for a in cal])
        cals.append(cal)
        caps_last.append(cal[-1][1])
        lastbp = max(lastbp, cal[-1][0])
    ids = []
    seen = {}
    for jb in jobs_in:
        jid = str(jb.get("id"))
        if jid in seen:
            continue
        seen[jid] = len(ids)
        ids.append(jid)
    jobs = [None] * len(ids)
    for jb in jobs_in:
        jid = str(jb.get("id"))
        if jobs[seen[jid]] is None:
            jobs[seen[jid]] = jb
    n = len(ids)

    def infeas(msg):
        state["output"] = {"status": "infeasible", "reason": msg}
        return state

    preds = [[] for _ in range(n)]
    succs = [[] for _ in range(n)]
    for j, jb in enumerate(jobs):
        ps = set()
        for p in (jb.get("after") or []):
            p = str(p)
            if p not in seen:
                return infeas("job %s references unknown predecessor %s" % (ids[j], p))
            ps.add(seen[p])
        if j in ps:
            return infeas("precedence cycle at job %s" % ids[j])
        preds[j] = sorted(ps)
        for p in ps:
            succs[p].append(j)
    indeg = [len(preds[j]) for j in range(n)]
    q = [j for j in range(n) if indeg[j] == 0]
    topo = []
    while q:
        j = q.pop()
        topo.append(j)
        for s in succs[j]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    if len(topo) < n:
        return infeas("precedence relation has a cycle")
    modes = []
    rel = []
    due = []
    wt = []
    for j, jb in enumerate(jobs):
        ml = []
        for mi, md in enumerate(jb.get("modes") or []):
            d = max(1, int(md.get("duration", 1)))
            req = []
            ok = True
            for rn, u in (md.get("requires") or {}).items():
                u = int(u)
                if rn not in ridx:
                    ok = False
                    break
                if u <= 0:
                    continue
                if u > caps_last[ridx[rn]]:
                    ok = False
                    break
                req.append((ridx[rn], u))
            if ok:
                ml.append((d, req, mi))
        if not ml:
            return infeas("job %s has no executable mode" % ids[j])
        modes.append(ml)
        rel.append(max(0, int(jb.get("release") or 0)))
        dd = jb.get("due")
        due.append(None if dd is None else int(dd))
        wt.append(max(0, int(jb.get("weight") or 0)))
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state

    nr = len(rnames)
    maxd = [max(m[0] for m in modes[j]) for j in range(n)]
    mind = [min(m[0] for m in modes[j]) for j in range(n)]
    H = max(lastbp, max(rel)) + sum(maxd) + 2 * max(maxd) + 10
    base = []
    for ri in range(nr):
        cal = cals[ri]
        arr = [0] * H
        for k, (t, c) in enumerate(cal):
            e = cal[k + 1][0] if k + 1 < len(cal) else H
            t = max(0, min(t, H))
            e = max(t, min(e, H))
            arr[t:e] = [c] * (e - t)
        base.append(arr)
    tardy = [due[j] is not None and wt[j] > 0 for j in range(n)]
    nm = [len(modes[j]) for j in range(n)]
    topo_pos = [0] * n
    for k, j in enumerate(topo):
        topo_pos[j] = k

    en = []
    for j in range(n):
        row = []
        for (d, req, _) in modes[j]:
            s = 0.0
            for (r, qq) in req:
                s += qq / float(max(1, caps_last[r]))
            row.append(d * s)
        en.append(row)
    minen = [max(1e-3, min(en[j])) for j in range(n)]

    anc = [0] * n
    for j in topo:
        m = 0
        for p in preds[j]:
            m |= anc[p] | (1 << p)
        anc[j] = m
    desc = [0] * n
    for j in reversed(topo):
        m = 0
        for s in succs[j]:
            m |= desc[s] | (1 << s)
        desc[j] = m

    def sgs(order, mvec, pre=0, pstart=None, pmode=None, limit=None, lam=0.0):
        av = [a[:] for a in base]
        start = [0] * n
        fin = [0] * n
        mch = [0] * n
        mk = 0
        td = 0
        for k in range(pre):
            j = order[k]
            t = pstart[j]
            m = pmode[j]
            d, req, _ = modes[j][m]
            e = t + d
            for (r, qq) in req:
                a = av[r]
                a[t:e] = [x - qq for x in a[t:e]]
            start[j] = t
            fin[j] = e
            mch[j] = m
            if e > mk:
                mk = e
            if tardy[j] and e > due[j]:
                td += wt[j] * (e - due[j])
        if limit is not None and mk + td > limit:
            return None
        for k in range(pre, len(order)):
            j = order[k]
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            mm = mvec[j]
            cand = range(nm[j]) if mm < 0 else (mm,)
            bt = -1
            bm = -1
            bf = 0
            bkey = None
            for m in cand:
                d, req, _ = modes[j][m]
                t = est
                if req:
                    while True:
                        e = t + d
                        moved = False
                        for (r, qq) in req:
                            a = av[r]
                            if min(a[t:e]) < qq:
                                tt = e - 1
                                while a[tt] >= qq:
                                    tt -= 1
                                t = tt + 1
                                moved = True
                                break
                        if not moved:
                            break
                f = t + d
                if mm < 0:
                    c = f - mk if f > mk else 0
                    if tardy[j] and f > due[j]:
                        c += wt[j] * (f - due[j])
                    key = (c + lam * en[j][m], f, en[j][m])
                    if bkey is None or key < bkey:
                        bkey = key
                        bt = t
                        bm = m
                        bf = f
                else:
                    bt = t
                    bm = m
                    bf = f
            d, req, _ = modes[j][bm]
            t = bt
            e = bf
            for (r, qq) in req:
                a = av[r]
                a[t:e] = [x - qq for x in a[t:e]]
            start[j] = t
            fin[j] = e
            mch[j] = bm
            if e > mk:
                mk = e
            if tardy[j] and e > due[j]:
                td += wt[j] * (e - due[j])
            if limit is not None and mk + td > limit:
                return None
        return (mk + td, start, mch)

    def fbi_order(st, mc):
        fin = [st[j] + modes[j][mc[j]][0] for j in range(n)]
        C = max(fin)
        ordb = sorted(range(n), key=lambda j: (-fin[j], -topo_pos[j]))
        av = [a[:] for a in base]
        bst = [0] * n
        for j in ordb:
            d, req, _ = modes[j][mc[j]]
            lim = C
            for s in succs[j]:
                if bst[s] < lim:
                    lim = bst[s]
            t = lim - d
            while True:
                if t < rel[j] or t < 0:
                    return None
                bad = -1
                for (r, qq) in req:
                    a = av[r]
                    if min(a[t:t + d]) < qq:
                        k = t
                        while a[k] >= qq:
                            k += 1
                        bad = k
                        break
                if bad < 0:
                    break
                t = bad - d
            bst[j] = t
            for (r, qq) in req:
                a = av[r]
                a[t:t + d] = [x - qq for x in a[t:t + d]]
        return sorted(range(n), key=lambda j: (bst[j], topo_pos[j]))

    def improve_fbi(c, st, mc, rounds=3):
        improved = False
        for _ in range(rounds):
            o = fbi_order(st, mc)
            if o is None:
                break
            res = sgs(o, mc, limit=c - 1)
            if res is None:
                break
            c, st, mc = res
            improved = True
        return improved, c, st, mc

    tail = [0] * n
    for j in reversed(topo):
        b = 0
        for s in succs[j]:
            if tail[s] > b:
                b = tail[s]
        tail[j] = b + mind[j]
    head = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            v = head[p] + mind[p]
            if v > e:
                e = v
        head[j] = e
    cp = max(head[j] + tail[j] for j in range(n))
    lft = [cp - tail[j] + mind[j] for j in range(n)]
    BIG = 10 ** 9
    dlf = [BIG] * n
    for j in reversed(topo):
        v = due[j] if tardy[j] else BIG
        for s in succs[j]:
            x = dlf[s] - mind[s]
            if x < v:
                v = x
        dlf[j] = v
    nsucc = [0] * n
    for j in reversed(topo):
        nsucc[j] = len(succs[j]) + sum(nsucc[s] for s in succs[j])
    Wd = [0.0] * n
    for j in reversed(topo):
        Wd[j] = (wt[j] if tardy[j] else 0) + 0.5 * sum(Wd[s] for s in succs[j])
    maxW = max(Wd) if max(Wd) > 0 else 1.0
    avgp = sum(mind) / float(n)
    sk = [min(lft[j], dlf[j]) for j in range(n)]
    tw = [wt[j] if tardy[j] else 0 for j in range(n)]
    Wall = []
    for j in range(n):
        s = tw[j]
        m = desc[j]
        x = 0
        while m:
            if m & 1:
                s += tw[x]
            m >>= 1
            x += 1
        Wall.append(float(s))
    tws = [tw[j] for j in range(n) if tardy[j]]
    wbar = (sum(tws) / float(len(tws))) if tws else 1.0
    lams = [0.0, 0.5 * wbar, 2.0 * wbar]

    raw_rules = []
    raw_rules.append([(lft[j], j) for j in range(n)])
    raw_rules.append([(sk[j], lft[j]) for j in range(n)])
    raw_rules.append([(sk[j], rel[j]) for j in range(n)])
    raw_rules.append([(-nsucc[j], lft[j]) for j in range(n)])
    raw_rules.append([(max(rel[j], head[j]), sk[j]) for j in range(n)])
    raw_rules.append([(-tail[j], sk[j]) for j in range(n)])
    atc = []
    for j in range(n):
        slack = max(0, dlf[j] - head[j] - mind[j]) if dlf[j] < BIG else BIG
        v = 0.0 if slack >= BIG else (Wd[j] + 1e-3) / mind[j] * math.exp(-slack / (2.0 * avgp))
        atc.append((-v, sk[j]))
    raw_rules.append(atc)
    raw_rules.append([(sk[j] - 0.5 * cp * Wd[j] / maxW, lft[j]) for j in range(n)])
    raw_rules.append([(head[j] + 0.5 * min(lft[j], dlf[j] if dlf[j] < BIG else lft[j]), j) for j in range(n)])
    raw_rules.append([(-(Wall[j] + 1e-3) / minen[j], sk[j]) for j in range(n)])
    raw_rules.append([((dlf[j] if dlf[j] < BIG else lft[j]) - avgp * Wall[j] / wbar, lft[j]) for j in range(n)])
    rules = []
    for rr in raw_rules:
        ordr = sorted(range(n), key=lambda j: rr[j])
        rk = [0] * n
        for p, j in enumerate(ordr):
            rk[j] = float(p)
        rules.append(rk)

    def make_order(prio, noise=0.0, rng=None):
        ind = [len(preds[j]) for j in range(n)]
        h = []
        for j in range(n):
            if ind[j] == 0:
                key = prio[j] + (rng.random() * noise if noise else 0.0)
                heapq.heappush(h, (key, j))
        out = []
        while h:
            _, j = heapq.heappop(h)
            out.append(j)
            for s in succs[j]:
                ind[s] -= 1
                if ind[s] == 0:
                    key = prio[s] + (rng.random() * noise if noise else 0.0)
                    heapq.heappush(h, (key, s))
        return out

    Wp = [Wall[j] + 1.0 for j in range(n)]
    ddl = [dlf[j] if dlf[j] < BIG else lft[j] for j in range(n)]

    def dispatch(K, gt, lam, noise, rng):
        av = [a[:] for a in base]
        start = [0] * n
        fin = [0] * n
        mch = [0] * n
        ind = [len(preds[j]) for j in range(n)]
        elig = [j for j in range(n) if ind[j] == 0]
        ct = {}
        for j in elig:
            ct[j] = [rel[j]] * nm[j]
        mk = 0
        td = 0
        Kp = K * avgp
        while elig:
            info = []
            bestf = None
            for j in elig:
                tl = ct[j]
                bkey = None
                bm = 0
                bt = 0
                bf = 0
                for m in range(nm[j]):
                    d, req, _ = modes[j][m]
                    t = tl[m]
                    if req:
                        while True:
                            e = t + d
                            moved = False
                            for (r, qq) in req:
                                a = av[r]
                                if min(a[t:e]) < qq:
                                    tt = e - 1
                                    while a[tt] >= qq:
                                        tt -= 1
                                    t = tt + 1
                                    moved = True
                                    break
                            if not moved:
                                break
                    tl[m] = t
                    f = t + d
                    c = f - mk if f > mk else 0
                    if tardy[j] and f > due[j]:
                        c += wt[j] * (f - due[j])
                    key = (c + lam * en[j][m], f)
                    if bkey is None or key < bkey:
                        bkey = key
                        bm = m
                        bt = t
                        bf = f
                info.append((j, bm, bt, bf))
                if bestf is None or bf < bestf:
                    bestf = bf
            if gt:
                cand = [x for x in info if x[2] < bestf]
                if not cand:
                    cand = info
            else:
                cand = info
            tmin = min(x[2] for x in cand)
            bv = -1.0
            ch = cand[0]
            for x in cand:
                j, m, t, f = x
                p = f - t
                slack = ddl[j] - f
                if slack < 0:
                    slack = 0
                v = Wp[j] / p * math.exp(-slack / Kp)
                if not gt:
                    v *= math.exp(-(t - tmin) / avgp)
                if noise:
                    v *= math.exp(noise * rng.gauss(0.0, 1.0))
                if v > bv:
                    bv = v
                    ch = x
            j, m, t, f = ch
            d, req, _ = modes[j][m]
            for (r, qq) in req:
                a = av[r]
                a[t:f] = [x - qq for x in a[t:f]]
            start[j] = t
            fin[j] = f
            mch[j] = m
            if f > mk:
                mk = f
            if tardy[j] and f > due[j]:
                td += wt[j] * (f - due[j])
            elig.remove(j)
            del ct[j]
            for s in succs[j]:
                ind[s] -= 1
                if ind[s] == 0:
                    est = rel[s]
                    for pp in preds[s]:
                        if fin[pp] > est:
                            est = fin[pp]
                    ct[s] = [est] * nm[s]
                    elig.append(s)
        return (mk + td, start, mch)

    rng = random.Random(12345)
    best = None
    pool = []

    def consider(order, res):
        nonlocal best
        c, st, mc = res
        o2 = sorted(order, key=lambda j: (st[j], topo_pos[j]))
        pool.append((c, o2, mc[:], st[:]))
        if best is None or c < best[0]:
            best = (c, o2, mc[:], st[:])

    allgreedy = [-1] * n
    fastm = [min(range(nm[j]), key=lambda m: (modes[j][m][0], en[j][m])) for j in range(n)]
    effm = [min(range(nm[j]), key=lambda m: (en[j][m], modes[j][m][0])) for j in range(n)]
    rule_best = []
    for ri, pr in enumerate(rules):
        o = make_order(pr)
        bb = None
        for li, lam in enumerate(lams):
            r1 = sgs(o, allgreedy, lam=lam)
            consider(o, r1)
            if bb is None or r1[0] < bb:
                bb = r1[0]
        r2 = sgs(o, fastm)
        consider(o, r2)
        r3 = sgs(o, effm)
        consider(o, r3)
        rule_best.append(min(bb, r2[0], r3[0]))
        if elapsed() > BUDGET * 0.13:
            break
    good_rule = min(range(len(rule_best)), key=lambda i: rule_best[i])

    nat = list(range(n))
    variants = []
    for gt in (True, False):
        for K in (1.0, 3.0, 0.5, 6.0):
            for lam in (0.0, lams[1]):
                variants.append((K, gt, lam))
    disp_best = []
    for (K, gt, lam) in variants:
        if elapsed() > BUDGET * 0.24:
            break
        res = dispatch(K, gt, lam, 0.0, rng)
        consider(nat, res)
        disp_best.append((res[0], K, gt, lam))
    disp_best.sort()
    t_disp_end = BUDGET * 0.28
    while disp_best and elapsed() < t_disp_end:
        _, K, gt, lam = disp_best[rng.randrange(min(3, len(disp_best)))]
        K2 = K * math.exp(rng.gauss(0.0, 0.4))
        res = dispatch(K2, gt, lam, 0.3 + 0.5 * rng.random(), rng)
        consider(nat, res)

    t_sample_end = BUDGET * 0.31
    while elapsed() < t_sample_end:
        if rng.random() < 0.5:
            pr = rules[good_rule]
        else:
            pr = rules[rng.randrange(len(rules))]
        o = make_order(pr, noise=n * 0.4 * rng.random(), rng=rng)
        u = rng.random()
        if u < 0.75:
            res = sgs(o, allgreedy, limit=best[0] * 1.15, lam=rng.choice(lams))
        elif u < 0.88:
            res = sgs(o, fastm, limit=best[0] * 1.15)
        else:
            res = sgs(o, effm, limit=best[0] * 1.15)
        if res is not None:
            consider(o, res)

    # ---------------- Squeaky-Wheel Optimisation (learned priorities) -------------
    def order_prio(order):
        pr = [0.0] * n
        for k, j in enumerate(order):
            pr[j] = float(k)
        return pr

    def rerank(pr):
        ordr = sorted(range(n), key=lambda j: (pr[j], topo_pos[j]))
        out = [0.0] * n
        for k, j in enumerate(ordr):
            out[j] = float(k)
        return out

    t_swo_end = BUDGET * 0.56
    prio = order_prio(best[1])
    swo_best = best[0]
    stall = 0
    it = 0
    rev_topo = list(reversed(topo))
    while elapsed() < t_swo_end:
        it += 1
        o = make_order(prio, noise=(1.5 if it > 1 else 0.0), rng=rng)
        mvec = allgreedy if rng.random() < 0.85 else best[2]
        res = sgs(o, mvec, lam=lams[it % len(lams)] if mvec is allgreedy else 0.0)
        c, st, mc = res
        consider(o, res)
        if c < swo_best:
            swo_best = c
            stall = 0
        else:
            stall += 1
        fin = [st[j] + modes[j][mc[j]][0] for j in range(n)]
        bl = [0.0] * n
        for j in range(n):
            if tardy[j] and fin[j] > due[j]:
                bl[j] += wt[j] * (fin[j] - due[j])
            if not succs[j] and fin[j] > cp:
                bl[j] += float(fin[j] - cp)
        for j in rev_topo:
            if bl[j] > 0:
                for p in preds[j]:
                    if fin[p] >= st[j]:
                        bl[p] += 0.6 * bl[j]
        mb = max(bl)
        if stall > 12 + n // 10:
            stall = 0
            src = best if rng.random() < 0.6 else pool[rng.randrange(len(pool))]
            prio = order_prio(src[1])
            prio = [prio[j] + rng.random() * 3.0 for j in range(n)]
            prio = rerank(prio)
            continue
        if mb <= 0:
            prio = rerank([prio[j] + rng.random() * 2.0 for j in range(n)])
            continue
        step = n * (0.1 + 0.4 * rng.random())
        cur_pos = order_prio(sorted(range(n), key=lambda j: (st[j], topo_pos[j])))
        newp = [0.5 * prio[j] + 0.5 * cur_pos[j] - step * (bl[j] / mb) for j in range(n)]
        prio = rerank(newp)

    pool.sort(key=lambda x: x[0])

    seen_c = set()
    cnt = 0
    for ent in list(pool[:12]):
        if cnt >= 5 or elapsed() > BUDGET * 0.62:
            break
        if ent[0] in seen_c:
            continue
        seen_c.add(ent[0])
        cnt += 1
        imp, c2, st2, mc2 = improve_fbi(ent[0], ent[3], ent[2])
        if imp:
            o2 = sorted(range(n), key=lambda j: (st2[j], topo_pos[j]))
            consider(o2, (c2, st2, mc2))
    pool.sort(key=lambda x: x[0])
    pool = pool[:20]

    cur_c, cur_o, cur_m, cur_s = best[0], best[1][:], best[2][:], best[3][:]
    multi = [j for j in range(n) if nm[j] > 1]
    T_start = max(0.5, 0.02 * best[0])
    t_ls0 = elapsed()
    total = max(1e-6, BUDGET - t_ls0)
    noimp = 0
    restarts = 0
    last_fbi_best = best[0]

    def pick_bad(st, mc):
        fin = [st[x] + modes[x][mc[x]][0] for x in range(n)]
        mk = max(fin)
        ws = []
        tot = 0.0
        for x in range(n):
            w = 0.0
            if tardy[x] and fin[x] > due[x]:
                w += wt[x] * (fin[x] - due[x])
            if fin[x] == mk:
                w += 1.0 + 0.05 * mk
            if w > 0:
                ws.append((x, w))
                tot += w
        if not ws:
            return rng.randrange(n), fin
        r = rng.random() * tot
        for x, w in ws:
            r -= w
            if r <= 0:
                return x, fin
        return ws[-1][0], fin

    while True:
        el = elapsed()
        if el >= BUDGET:
            break
        frac = (el - t_ls0) / total
        T = T_start * (1 - frac) + 0.05
        o = cur_o[:]
        mv = cur_m[:]
        lam = 0.0
        rmv = rng.random()
        firstpos = n
        if multi and rmv < 0.18:
            if rng.random() < 0.4:
                j, _ = pick_bad(cur_s, cur_m)
                if nm[j] < 2:
                    j = rng.choice(multi)
            else:
                j = rng.choice(multi)
            if rng.random() < 0.2:
                mv[j] = -1
                lam = rng.choice(lams)
            else:
                m = rng.randrange(nm[j] - 1)
                if m >= mv[j]:
                    m += 1
                mv[j] = m
            firstpos = o.index(j)
            if rng.random() < 0.25:
                rmv = 0.9
        elif multi and rmv < 0.28:
            p = rng.randrange(n)
            if rng.random() < 0.5:
                L = rng.randint(3, max(3, n // 4))
                seg = o[p:p + L]
            else:
                seg = o[p:]
            for x in seg:
                mv[x] = -1
            lam = rng.choice(lams) * (0.5 + rng.random())
            firstpos = p
        elif rmv < 0.50:
            j, fin = pick_bad(cur_s, cur_m)
            i = o.index(j)
            if i > 0:
                span = rng.randint(1, max(1, min(i, n // 2 if rng.random() < 0.7 else i)))
                p = i - span
                am = anc[j] | (1 << j)
                segm = o[p:i + 1]
                blk = [x for x in segm if (am >> x) & 1]
                rst = [x for x in segm if not (am >> x) & 1]
                o[p:i + 1] = blk + rst
                firstpos = p
        elif rmv < 0.60:
            if rng.random() < 0.5:
                bj, fin = pick_bad(cur_s, cur_m)
                cands = [x for x in range(n) if cur_s[x] < cur_s[bj] and not tardy[x] and not ((anc[bj] >> x) & 1)]
                j = rng.choice(cands) if cands else rng.randrange(n)
            else:
                j = rng.randrange(n)
            i = o.index(j)
            if i < n - 1:
                qe = min(n - 1, i + rng.randint(1, max(1, n // 3)))
                dm = desc[j] | (1 << j)
                segm = o[i:qe + 1]
                blk = [x for x in segm if (dm >> x) & 1]
                rst = [x for x in segm if not (dm >> x) & 1]
                o[i:qe + 1] = rst + blk
                firstpos = i
        if rmv >= 0.60:
            if rng.random() < 0.45:
                j, fin = pick_bad(cur_s, cur_m)
                while rng.random() < 0.45:
                    tight = [p for p in preds[j] if fin[p] >= cur_s[j]]
                    if not tight:
                        break
                    j = rng.choice(tight)
                early = True
            else:
                j = rng.randrange(n)
                early = False
            i = o.index(j)
            o.pop(i)
            pos = {x: k for k, x in enumerate(o)}
            lo = 0
            for p in preds[j]:
                if pos[p] + 1 > lo:
                    lo = pos[p] + 1
            hi = len(o)
            for s in succs[j]:
                if pos[s] < hi:
                    hi = pos[s]
            if early:
                hi = min(hi, i)
            if hi < lo:
                hi = lo
            if rng.random() < 0.5:
                np_ = min(max(i + rng.randint(-8, 8), lo), hi)
            else:
                np_ = rng.randint(lo, hi)
            o.insert(np_, j)
            firstpos = min(firstpos, i, np_)
        if o == cur_o and mv == cur_m:
            continue
        u = rng.random()
        thr = cur_c - T * math.log(max(u, 1e-12))
        res = sgs(o, mv, pre=firstpos, pstart=cur_s, pmode=cur_m, limit=thr, lam=lam)
        if res is None:
            noimp += 1
        else:
            c, st, mc = res
            cur_c = c
            cur_o = sorted(o, key=lambda x: (st[x], topo_pos[x]))
            cur_m = mc
            cur_s = st
            if c < best[0]:
                best = (c, cur_o[:], cur_m[:], cur_s[:])
                noimp = 0
                if c < last_fbi_best and elapsed() < BUDGET - 0.02:
                    last_fbi_best = c
                    imp, c2, st2, mc2 = improve_fbi(c, st, mc, 2)
                    if imp:
                        o2 = sorted(range(n), key=lambda x: (st2[x], topo_pos[x]))
                        best = (c2, o2[:], mc2[:], st2[:])
                        cur_c, cur_o, cur_m, cur_s = c2, o2, mc2[:], st2[:]
                        last_fbi_best = c2
            else:
                noimp += 1
        if noimp > 300 + 3 * n:
            noimp = 0
            restarts += 1
            if restarts % 2 or not pool:
                src = best
            else:
                src = pool[rng.randrange(min(5, len(pool)))]
            cur_c, cur_o, cur_m, cur_s = src[0], src[1][:], src[2][:], src[3][:]

    c, o, mc, st = best

    def valid(st, mc):
        use = [[0] * H for _ in range(nr)]
        for j in range(n):
            if st[j] < rel[j] or st[j] < 0:
                return False
            d = modes[j][mc[j]][0]
            if st[j] + d > H:
                return False
            for p in preds[j]:
                if st[j] < st[p] + modes[p][mc[p]][0]:
                    return False
            for (r, qq) in modes[j][mc[j]][1]:
                a = use[r]
                for t in range(st[j], st[j] + d):
                    a[t] += qq
        for r in range(nr):
            a = use[r]
            b = base[r]
            for t in range(H):
